import torch
import torch.nn as nn
import matplotlib.pyplot as plt

class UniversalLooseScrew(nn.Module):
    def __init__(self, mode='rattle'):
        super().__init__()
        self.mode = mode
        # Learnable 'Looseness'
        self.looseness = nn.Parameter(torch.tensor(0.1))
        self.pressure_sensitivity = nn.Parameter(torch.tensor(0.5))

    def forward(self, x):
        if x.dim() == 0: return x # safety for scalars

        pos = torch.relu(x)
        neg_mask = (x < 0).float()
        pressure = torch.abs(x)

        # Calculate 'Alpha' (The state of the screw)
        alpha = torch.sigmoid(self.pressure_sensitivity * pressure)

        if self.mode == 'boring':
            # Standard Leaky ReLU (0.01 slope)
            neg = 0.01 * x
        elif self.mode == 'safe':
            # ChatGPT's approach: bended line
            neg = x * (1.0 - (self.looseness * alpha * torch.tanh(pressure)))
        elif self.mode == 'rattle':
            # The VLF approach: The 'Dance'
            # We use tanh(x^2) to keep it from exploding but keep the curve
            neg = x + (self.looseness * alpha * torch.tanh(x**2))

        return pos + (neg * neg_mask)

# --- VISUALIZATION TEST ---
x = torch.linspace(-3, 3, 200)
modes = ['boring', 'safe', 'rattle']

plt.figure(figsize=(10, 6))
