print("device:", device)

torch.backends.cudnn.benchmark = False

SEEDS = [0, 1, 2, 3, 4]   # change to [0, 1, 2] for faster runs
BATCH_SIZE = 256
HIDDEN_DIM = 64
LR = 1e-3
WEIGHT_DECAY = 1e-4
PATIENCE = 6
THRESH_DEAD = 1e-4

NOISE_LEVELS_CLASS = [0.0, 0.1, 0.25]
NOISE_LEVELS_REG = [0.0, 0.05, 0.15]


def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def sigma_tag(sigma: float) -> str:
    return str(sigma).replace(".", "p")


# ----------------------------
# Activations
# ----------------------------
class PressureRattleActivation(nn.Module):
    """
    Safe version:
    negative side is pulled toward zero by a bounded, pressure-aware factor.
    """
    def __init__(self, init_a=0.5, init_b=-1.0, init_lambda=0.5):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(float(init_a)))
        self.b = nn.Parameter(torch.tensor(float(init_b)))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(float(init_lambda))))

    def forward(self, x):
        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        rattle = lam * alpha * torch.tanh(pressure)
        pos = torch.relu(x)
        neg = x * (1.0 - rattle)
        return torch.where(x >= 0, pos, neg)


class QuadraticRattleActivation(nn.Module):
    """
    Stronger version:
    uses a bounded quadratic pressure term on the negative side.
    """
    def __init__(self, init_a=0.5, init_b=-1.0, init_lambda=0.5):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(float(init_a)))
        self.b = nn.Parameter(torch.tensor(float(init_b)))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(float(init_lambda))))

    def forward(self, x):
        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        quadratic_pressure = (pressure ** 2) / (1.0 + pressure ** 2)
        rattle = lam * alpha * quadratic_pressure
        pos = torch.relu(x)
        neg = x + rattle
        return torch.where(x >= 0, pos, neg)


class DualPathRattleActivation(nn.Module):
    """
    New version:
    clean path + separate leak path.
    This keeps the main signal intact and adds a second signal channel.
    """
    def __init__(self, init_a=0.5, init_b=-1.0, init_lambda=0.1):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(float(init_a)))
        self.b = nn.Parameter(torch.tensor(float(init_b)))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(float(init_lambda))))

    def forward(self, x):
        clean = torch.relu(x)

        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)

        # separate leak signal, sign-preserving, bounded, and stable
        leak = lam * alpha * torch.tanh(pressure) * torch.sign(x)

        return clean + leak


def make_activation(name: str) -> nn.Module:
    if name == "relu":
        return nn.ReLU()
    if name == "leaky_relu":
        return nn.LeakyReLU(0.01)
    if name == "pressure_rattle":
        return PressureRattleActivation()
    if name == "quadratic_rattle":
        return QuadraticRattleActivation()
    if name == "dual_path_rattle":
        return DualPathRattleActivation()
    raise ValueError(f"Unknown activation: {name}")


# ----------------------------
# Model
# ----------------------------
class MLP(nn.Module):
    def __init__(self, input_dim, hidden_dim, output_dim, activation_name):
        super().__init__()
        self.fc1 = nn.Linear(input_dim, hidden_dim)
        self.act1 = make_activation(activation_name)
        self.fc2 = nn.Linear(hidden_dim, hidden_dim)
        self.act2 = make_activation(activation_name)
        self.out = nn.Linear(hidden_dim, output_dim)

    def forward(self, x, return_hidden=False):
        h1 = self.act1(self.fc1(x))
        h2 = self.act2(self.fc2(h1))
        out = self.out(h2)
        if return_hidden:
            return out, (h1, h2)
        return out


# ----------------------------
# Data generation
# ----------------------------
def make_xor(n=4000, seed=0):
    rng = np.random.default_rng(seed)
    X = rng.uniform(-1.5, 1.5, size=(n, 2)).astype(np.float32)
    y = ((X[:, 0] > 0) ^ (X[:, 1] > 0)).astype(np.int64)
    flip = rng.random(n) < 0.05
    y[flip] = 1 - y[flip]
    return X, y


def make_sine_regression(n=4000, seed=0):
    rng = np.random.default_rng(seed)
    x = rng.uniform(-4.0, 4.0, size=(n, 1)).astype(np.float32)
    y = (np.sin(3.0 * x[:, 0]) + 0.3 * x[:, 0] + rng.normal(0.0, 0.15, size=n)).astype(np.float32)
    return x, y.reshape(-1, 1)


def load_digits_data():
    digits = load_digits()
    X = digits.data.astype(np.float32)
    y = digits.target.astype(np.int64)
    return X, y


def split_and_scale(X, y, task_type, seed):
    if task_type == "classification":
        X_temp, X_test, y_temp, y_test = train_test_split(
            X, y, test_size=0.2, random_state=seed, stratify=y
        )
        X_train, X_val, y_train, y_val = train_test_split(
            X_temp, y_temp, test_size=0.25, random_state=seed, stratify=y_temp
        )
    else:
        X_temp, X_test, y_temp, y_test = train_test_split(
            X, y, test_size=0.2, random_state=seed
        )
        X_train, X_val, y_train, y_val = train_test_split(
            X_temp, y_temp, test_size=0.25, random_state=seed
        )

    scaler = StandardScaler()
    X_train = scaler.fit_transform(X_train).astype(np.float32)
    X_val = scaler.transform(X_val).astype(np.float32)
    X_test = scaler.transform(X_test).astype(np.float32)

    if task_type == "classification":
        y_train = y_train.astype(np.int64)
        y_val = y_val.astype(np.int64)
        y_test = y_test.astype(np.int64)
    else:
        y_train = y_train.astype(np.float32)
        y_val = y_val.astype(np.float32)
        y_test = y_test.astype(np.float32)

    return X_train, X_val, X_test, y_train, y_val, y_test


def make_loaders(X_train, y_train, X_val, y_val, X_test, y_test, task_type):
    if task_type == "classification":
        y_train_t = torch.tensor(y_train, dtype=torch.long)
        y_val_t = torch.tensor(y_val, dtype=torch.long)
        y_test_t = torch.tensor(y_test, dtype=torch.long)
    else:
        y_train_t = torch.tensor(y_train, dtype=torch.float32)
        y_val_t = torch.tensor(y_val, dtype=torch.float32)
        y_test_t = torch.tensor(y_test, dtype=torch.float32)

    train_ds = TensorDataset(torch.tensor(X_train, dtype=torch.float32), y_train_t)
    val_ds = TensorDataset(torch.tensor(X_val, dtype=torch.float32), y_val_t)
    test_ds = TensorDataset(torch.tensor(X_test, dtype=torch.float32), y_test_t)

    train_loader = DataLoader(train_ds, batch_size=BATCH_SIZE, shuffle=True, drop_last=False)
    val_loader = DataLoader(val_ds, batch_size=BATCH_SIZE, shuffle=False, drop_last=False)
    test_loader = DataLoader(test_ds, batch_size=BATCH_SIZE, shuffle=False, drop_last=False)
    return train_loader, val_loader, test_loader


TASKS = {
    "xor": {
        "kind": "classification",
        "builder": lambda seed: make_xor(n=4000, seed=seed),
        "noise_levels": NOISE_LEVELS_CLASS,
        "epochs": 40,
        "num_classes": 2,
    },
    "moons": {
        "kind": "classification",
        "builder": lambda seed: make_moons(n_samples=4000, noise=0.25, random_state=seed),
        "noise_levels": NOISE_LEVELS_CLASS,
        "epochs": 40,
        "num_classes": 2,
    },
    "circles": {
        "kind": "classification",
        "builder": lambda seed: make_circles(n_samples=4000, factor=0.5, noise=0.15, random_state=seed),
        "noise_levels": NOISE_LEVELS_CLASS,
        "epochs": 40,
        "num_classes": 2,
    },
    "digits": {
        "kind": "classification",
        "builder": lambda seed: load_digits_data(),
        "noise_levels": [0.0, 0.2, 0.5],
        "epochs": 50,
        "num_classes": 10,
    },
    "sine_regression": {
        "kind": "regression",
        "builder": lambda seed: make_sine_regression(n=4000, seed=seed),
        "noise_levels": NOISE_LEVELS_REG,
        "epochs": 50,
        "num_classes": 1,
    },
}

ACTIVATIONS = ["relu", "leaky_relu", "pressure_rattle", "quadratic_rattle", "dual_path_rattle"]


# ----------------------------
# Training / evaluation
# ----------------------------
def evaluate_model(model, loader, task_type, noise_sigma=0.0, noise_seed=0):
    model.eval()
    criterion = nn.CrossEntropyLoss() if task_type == "classification" else nn.MSELoss()

    total_loss = 0.0
    total_n = 0
    all_true = []
    all_pred = []

    gen = torch.Generator(device=device)
    gen.manual_seed(int(noise_seed))

    with torch.no_grad():
        for xb, yb in loader:
            xb = xb.to(device)
            yb = yb.to(device)

            if noise_sigma > 0:
                noise = torch.randn(xb.shape, generator=gen, dtype=xb.dtype, device=device) * noise_sigma
                xb = xb + noise

            out = model(xb)

            if task_type == "classification":
                loss = criterion(out, yb)
                pred = out.argmax(dim=1)
                total_loss += loss.item() * xb.size(0)
                total_n += xb.size(0)
                all_true.append(yb.detach().cpu().numpy())
                all_pred.append(pred.detach().cpu().numpy())
            else:
                out = out.view(-1, 1)
                yb = yb.view(-1, 1)
                loss = criterion(out, yb)
                total_loss += loss.item() * xb.size(0)
                total_n += xb.size(0)
                all_true.append(yb.detach().cpu().numpy().reshape(-1))
                all_pred.append(out.detach().cpu().numpy().reshape(-1))

    metrics = {"loss": total_loss / max(total_n, 1)}

    if task_type == "classification":
        y_true = np.concatenate(all_true)
        y_pred = np.concatenate(all_pred)
        metrics["acc"] = float((y_true == y_pred).mean())
    else:
        y_true = np.concatenate(all_true)
        y_pred = np.concatenate(all_pred)
        metrics["mse"] = float(np.mean((y_true - y_pred) ** 2))
        metrics["mae"] = float(np.mean(np.abs(y_true - y_pred)))
        metrics["r2"] = float(r2_score(y_true, y_pred))

    return metrics


def dead_unit_rate(model, loader, hidden_dim):
    model.eval()
    sums = [
        torch.zeros(hidden_dim, device=device),
        torch.zeros(hidden_dim, device=device),
    ]
    count = 0

    with torch.no_grad():
        for xb, _ in loader:
            xb = xb.to(device)
            _, (h1, h2) = model(xb, return_hidden=True)
            sums[0] += h1.abs().sum(dim=0)
            sums[1] += h2.abs().sum(dim=0)
            count += xb.size(0)

    dead_rates = []
    for s in sums:
        mean_abs = (s / max(count, 1)).detach().cpu()
        dead_rates.append(float((mean_abs < THRESH_DEAD).float().mean().item()))
    return float(np.mean(dead_rates)), dead_rates


def train_model(model, train_loader, val_loader, task_type, max_epochs):
    criterion = nn.CrossEntropyLoss() if task_type == "classification" else nn.MSELoss()
    opt = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)

    best_state = copy.deepcopy(model.state_dict())
    best_val_loss = float("inf")
    best_epoch = 0
    wait = 0
    history = []

    for epoch in range(1, max_epochs + 1):
        model.train()
        train_loss = 0.0
        train_n = 0

        for xb, yb in train_loader:
            xb = xb.to(device)
            yb = yb.to(device)

            opt.zero_grad()
            out = model(xb)

            if task_type == "classification":
                loss = criterion(out, yb)
            else:
                loss = criterion(out.view(-1, 1), yb.view(-1, 1))

            loss.backward()
            opt.step()

            train_loss += loss.item() * xb.size(0)
            train_n += xb.size(0)

        train_loss /= max(train_n, 1)
        val_metrics = evaluate_model(model, val_loader, task_type)
        val_loss = val_metrics["loss"]

        history.append({
            "epoch": epoch,
            "train_loss": train_loss,
            "val_loss": val_loss,
            **val_metrics,
        })

        if val_loss < best_val_loss - 1e-6:
            best_val_loss = val_loss
            best_state = copy.deepcopy(model.state_dict())
            best_epoch = epoch
            wait = 0
        else:
            wait += 1

        if wait >= PATIENCE:
            break

    model.load_state_dict(best_state)
    return history, best_epoch, best_val_loss


# ----------------------------
# Main stress test loop
# ----------------------------
results = []
start_time = time.time()

for seed in SEEDS:
    for task_name, cfg in TASKS.items():
        set_seed(seed)

        X, y = cfg["builder"](seed)
        task_type = cfg["kind"]

        X_train, X_val, X_test, y_train, y_val, y_test = split_and_scale(X, y, task_type, seed)
        train_loader, val_loader, test_loader = make_loaders(
            X_train, y_train, X_val, y_val, X_test, y_test, task_type
        )

        input_dim = X_train.shape[1]
        output_dim = cfg["num_classes"] if task_type == "classification" else 1

        for act_name in ACTIVATIONS:
            set_seed(seed)

            model = MLP(input_dim, HIDDEN_DIM, output_dim, act_name).to(device)
            t0 = time.time()
            history, best_epoch, best_val_loss = train_model(
                model, train_loader, val_loader, task_type, max_epochs=cfg["epochs"]
            )
            train_time = time.time() - t0

            train_metrics = evaluate_model(model, train_loader, task_type, noise_sigma=0.0, noise_seed=seed)
            val_metrics = evaluate_model(model, val_loader, task_type, noise_sigma=0.0, noise_seed=seed)
            test_metrics = evaluate_model(model, test_loader, task_type, noise_sigma=0.0, noise_seed=seed)

            dead_avg, dead_layers = dead_unit_rate(model, train_loader, HIDDEN_DIM)

            row = {
                "seed": seed,
                "task": task_name,
                "kind": task_type,
                "activation": act_name,
                "epochs_ran": len(history),
                "best_epoch": best_epoch,
                "best_val_loss": best_val_loss,
                "train_time_sec": train_time,
                "dead_rate_avg": dead_avg,
                "dead_rate_layer1": dead_layers[0],
                "dead_rate_layer2": dead_layers[1],
                "train_loss": train_metrics["loss"],
                "val_loss": val_metrics["loss"],
                "test_loss": test_metrics["loss"],
            }

            if task_type == "classification":
                row["train_acc"] = train_metrics["acc"]
                row["val_acc"] = val_metrics["acc"]
                row["test_acc"] = test_metrics["acc"]

                for sigma in cfg["noise_levels"]:
                    noisy_metrics = evaluate_model(
                        model, test_loader, task_type,
                        noise_sigma=sigma,
                        noise_seed=seed + int(sigma * 1000) + 17
                    )
                    row[f"test_acc_noise_{sigma_tag(sigma)}"] = noisy_metrics["acc"]
            else:
                row["train_mse"] = train_metrics["mse"]
                row["val_mse"] = val_metrics["mse"]
                row["test_mse"] = test_metrics["mse"]
                row["train_mae"] = train_metrics["mae"]
                row["val_mae"] = val_metrics["mae"]
                row["test_mae"] = test_metrics["mae"]
                row["test_r2"] = test_metrics["r2"]

                for sigma in cfg["noise_levels"]:
                    noisy_metrics = evaluate_model(
                        model, test_loader, task_type,
                        noise_sigma=sigma,
                        noise_seed=seed + int(sigma * 1000) + 17
                    )
                    row[f"test_r2_noise_{sigma_tag(sigma)}"] = noisy_metrics["r2"]
                    row[f"test_mse_noise_{sigma_tag(sigma)}"] = noisy_metrics["mse"]

            results.append(row)

            print(
                f"[seed {seed} | {task_name:15s} | {act_name:16s}] "
                f"best_epoch={best_epoch:02d} "
                f"val_loss={best_val_loss:.4f} "
                f"test_loss={test_metrics['loss']:.4f} "
                f"dead={dead_avg:.3f} "
                f"time={train_time:.1f}s"
            )

            del model
            if device.type == "cuda":
                torch.cuda.empty_cache()

results_df = pd.DataFrame(results)
print("\nTotal runtime (min):", round((time.time() - start_time) / 60.0, 2))
print("\nRaw results sample:")
display(results_df.head())

# ----------------------------
# Summaries
# ----------------------------
pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 180)

for task_name, cfg in TASKS.items():
    print("\n" + "=" * 90)
    print("TASK:", task_name, "|", cfg["kind"])
    sub = results_df[results_df["task"] == task_name].copy()

    if cfg["kind"] == "classification":
        cols = ["test_acc", "dead_rate_avg", "best_val_loss", "epochs_ran", "train_time_sec"]
        summary = sub.groupby("activation")[cols].agg(["mean", "std"]).round(4)
        display(summary)

        print("\nNoisy test accuracy:")
        noise_cols = [f"test_acc_noise_{sigma_tag(s)}" for s in cfg["noise_levels"]]
        noise_summary = sub.groupby("activation")[noise_cols].agg(["mean", "std"]).round(4)
        display(noise_summary)

        ranking = sub.groupby("activation")["test_acc"].mean().sort_values(ascending=False)
        print("\nMean clean test accuracy ranking:")
        print(ranking)

    else:
        cols = ["test_r2", "test_mse", "test_mae", "dead_rate_avg", "best_val_loss", "epochs_ran", "train_time_sec"]
        summary = sub.groupby("activation")[cols].agg(["mean", "std"]).round(4)
        display(summary)

        print("\nNoisy test R2:")
        noise_cols = [f"test_r2_noise_{sigma_tag(s)}" for s in cfg["noise_levels"]]
        noise_summary = sub.groupby("activation")[noise_cols].agg(["mean", "std"]).round(4)
        display(noise_summary)

        ranking = sub.groupby("activation")["test_r2"].mean().sort_values(ascending=False)
        print("\nMean clean test R2 ranking:")
        print(ranking)

print("\nDone.")

# Stress test for the Loose Screw / Mixed-Dual-Path Rattle idea
# Copy this into ONE Colab cell and run.

import copy
import time
import random
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
from torch.utils.data import TensorDataset, DataLoader
from sklearn.datasets import make_moons, make_circles, load_digits
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import r2_score
from IPython.display import display

# ----------------------------
# Repro + device
# ----------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("device:", device)

torch.backends.cudnn.benchmark = False

SEEDS = [0, 1, 2, 3, 4]   # change to [0, 1, 2] for faster runs
BATCH_SIZE = 256
HIDDEN_DIM = 64
LR = 1e-3
WEIGHT_DECAY = 1e-4
PATIENCE = 6
THRESH_DEAD = 1e-4

NOISE_LEVELS_CLASS = [0.0, 0.1, 0.25]
NOISE_LEVELS_REG = [0.0, 0.05, 0.15]


def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def sigma_tag(sigma: float) -> str:
    return str(sigma).replace(".", "p")


# ----------------------------
# Activations
# ----------------------------
class PressureRattleActivation(nn.Module):
    """
    Safe version:
    negative side is pulled toward zero by a bounded, pressure-aware factor.
    """
    def __init__(self, init_a=0.5, init_b=-1.0, init_lambda=0.5):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(float(init_a)))
        self.b = nn.Parameter(torch.tensor(float(init_b)))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(float(init_lambda))))

    def forward(self, x):
        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        rattle = lam * alpha * torch.tanh(pressure)
        pos = torch.relu(x)
        neg = x * (1.0 - rattle)
        return torch.where(x >= 0, pos, neg)


class QuadraticRattleActivation(nn.Module):
    """
    Stronger version:
    uses a bounded quadratic pressure term on the negative side.
    """
    def __init__(self, init_a=0.5, init_b=-1.0, init_lambda=0.5):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(float(init_a)))
        self.b = nn.Parameter(torch.tensor(float(init_b)))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(float(init_lambda))))

    def forward(self, x):
        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        quadratic_pressure = (pressure ** 2) / (1.0 + pressure ** 2)
        rattle = lam * alpha * quadratic_pressure
        pos = torch.relu(x)
        neg = x + rattle
        return torch.where(x >= 0, pos, neg)


class DualPathRattleActivation(nn.Module):
    """
    Clean path + separate leak path.
    This keeps the main signal intact and adds a second signal channel.
    """
    def __init__(self, init_a=0.5, init_b=-1.0, init_lambda=0.1):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(float(init_a)))
        self.b = nn.Parameter(torch.tensor(float(init_b)))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(float(init_lambda))))

    def forward(self, x):
        clean = torch.relu(x)

        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)

        leak = lam * alpha * torch.tanh(x)
        return clean + leak


class MixedDualPathRattleActivation(nn.Module):
    """
    Clean path + leak path, with a learnable mix between them.
    This is the next framework step: the model learns how much to trust each path.
    """
    def __init__(self, init_a=0.5, init_b=-1.0, init_lambda=0.1, init_mix_clean=1.5, init_mix_leak=-1.5):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(float(init_a)))
        self.b = nn.Parameter(torch.tensor(float(init_b)))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(float(init_lambda))))
        self.mix_logits = nn.Parameter(torch.tensor([float(init_mix_clean), float(init_mix_leak)]))

    def forward(self, x):
        clean = torch.relu(x)

        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        leak = lam * alpha * torch.tanh(x)

        weights = torch.softmax(self.mix_logits, dim=0)
        return weights[0] * clean + weights[1] * leak


def make_activation(name: str) -> nn.Module:
    if name == "relu":
        return nn.ReLU()
    if name == "leaky_relu":
        return nn.LeakyReLU(0.01)
    if name == "pressure_rattle":
        return PressureRattleActivation()
    if name == "quadratic_rattle":
        return QuadraticRattleActivation()
    if name == "dual_path_rattle":
        return DualPathRattleActivation()
    if name == "mixed_dual_path_rattle":
        return MixedDualPathRattleActivation()
    raise ValueError(f"Unknown activation: {name}")


# ----------------------------
# Model
# ----------------------------
class MLP(nn.Module):
    def __init__(self, input_dim, hidden_dim, output_dim, activation_name):
        super().__init__()
        self.fc1 = nn.Linear(input_dim, hidden_dim)
        self.act1 = make_activation(activation_name)
        self.fc2 = nn.Linear(hidden_dim, hidden_dim)
        self.act2 = make_activation(activation_name)
        self.out = nn.Linear(hidden_dim, output_dim)

    def forward(self, x, return_hidden=False):
        h1 = self.act1(self.fc1(x))
        h2 = self.act2(self.fc2(h1))
        out = self.out(h2)
        if return_hidden:
            return out, (h1, h2)
        return out


# ----------------------------
# Data generation
# ----------------------------
def make_xor(n=4000, seed=0):
    rng = np.random.default_rng(seed)
    X = rng.uniform(-1.5, 1.5, size=(n, 2)).astype(np.float32)
    y = ((X[:, 0] > 0) ^ (X[:, 1] > 0)).astype(np.int64)
    flip = rng.random(n) < 0.05
    y[flip] = 1 - y[flip]
    return X, y


def make_sine_regression(n=4000, seed=0):
    rng = np.random.default_rng(seed)
    x = rng.uniform(-4.0, 4.0, size=(n, 1)).astype(np.float32)
    y = (np.sin(3.0 * x[:, 0]) + 0.3 * x[:, 0] + rng.normal(0.0, 0.15, size=n)).astype(np.float32)
    return x, y.reshape(-1, 1)


def load_digits_data():
    digits = load_digits()
    X = digits.data.astype(np.float32)
    y = digits.target.astype(np.int64)
    return X, y


def split_and_scale(X, y, task_type, seed):
    if task_type == "classification":
        X_temp, X_test, y_temp, y_test = train_test_split(
            X, y, test_size=0.2, random_state=seed, stratify=y
        )
        X_train, X_val, y_train, y_val = train_test_split(
            X_temp, y_temp, test_size=0.25, random_state=seed, stratify=y_temp
        )
    else:
        X_temp, X_test, y_temp, y_test = train_test_split(
            X, y, test_size=0.2, random_state=seed
        )
        X_train, X_val, y_train, y_val = train_test_split(
            X_temp, y_temp, test_size=0.25, random_state=seed
        )

    scaler = StandardScaler()
    X_train = scaler.fit_transform(X_train).astype(np.float32)
    X_val = scaler.transform(X_val).astype(np.float32)
    X_test = scaler.transform(X_test).astype(np.float32)

    if task_type == "classification":
        y_train = y_train.astype(np.int64)
        y_val = y_val.astype(np.int64)
        y_test = y_test.astype(np.int64)
    else:
        y_train = y_train.astype(np.float32)
        y_val = y_val.astype(np.float32)
        y_test = y_test.astype(np.float32)

    return X_train, X_val, X_test, y_train, y_val, y_test


def make_loaders(X_train, y_train, X_val, y_val, X_test, y_test, task_type):
    if task_type == "classification":
        y_train_t = torch.tensor(y_train, dtype=torch.long)
        y_val_t = torch.tensor(y_val, dtype=torch.long)
        y_test_t = torch.tensor(y_test, dtype=torch.long)
    else:
        y_train_t = torch.tensor(y_train, dtype=torch.float32)
        y_val_t = torch.tensor(y_val, dtype=torch.float32)
        y_test_t = torch.tensor(y_test, dtype=torch.float32)

    train_ds = TensorDataset(torch.tensor(X_train, dtype=torch.float32), y_train_t)
    val_ds = TensorDataset(torch.tensor(X_val, dtype=torch.float32), y_val_t)
    test_ds = TensorDataset(torch.tensor(X_test, dtype=torch.float32), y_test_t)

    train_loader = DataLoader(train_ds, batch_size=BATCH_SIZE, shuffle=True, drop_last=False)
    val_loader = DataLoader(val_ds, batch_size=BATCH_SIZE, shuffle=False, drop_last=False)
    test_loader = DataLoader(test_ds, batch_size=BATCH_SIZE, shuffle=False, drop_last=False)
    return train_loader, val_loader, test_loader


TASKS = {
    "xor": {
        "kind": "classification",
        "builder": lambda seed: make_xor(n=4000, seed=seed),
        "noise_levels": NOISE_LEVELS_CLASS,
        "epochs": 40,
        "num_classes": 2,
    },
    "moons": {
        "kind": "classification",
        "builder": lambda seed: make_moons(n_samples=4000, noise=0.25, random_state=seed),
        "noise_levels": NOISE_LEVELS_CLASS,
        "epochs": 40,
        "num_classes": 2,
    },
    "circles": {
        "kind": "classification",
        "builder": lambda seed: make_circles(n_samples=4000, factor=0.5, noise=0.15, random_state=seed),
        "noise_levels": NOISE_LEVELS_CLASS,
        "epochs": 40,
        "num_classes": 2,
    },
    "digits": {
        "kind": "classification",
        "builder": lambda seed: load_digits_data(),
        "noise_levels": [0.0, 0.2, 0.5],
        "epochs": 50,
        "num_classes": 10,
    },
    "sine_regression": {
        "kind": "regression",
        "builder": lambda seed: make_sine_regression(n=4000, seed=seed),
        "noise_levels": NOISE_LEVELS_REG,
        "epochs": 50,
        "num_classes": 1,
    },
}

ACTIVATIONS = [
    "relu",
    "leaky_relu",
    "pressure_rattle",
    "quadratic_rattle",
    "dual_path_rattle",
    "mixed_dual_path_rattle",
]


# ----------------------------
# Training / evaluation
# ----------------------------
def evaluate_model(model, loader, task_type, noise_sigma=0.0, noise_seed=0):
    model.eval()
    criterion = nn.CrossEntropyLoss() if task_type == "classification" else nn.MSELoss()

    total_loss = 0.0
    total_n = 0
    all_true = []
    all_pred = []

    gen = torch.Generator(device=device)
    gen.manual_seed(int(noise_seed))

    with torch.no_grad():
        for xb, yb in loader:
            xb = xb.to(device)
            yb = yb.to(device)

            if noise_sigma > 0:
                noise = torch.randn(xb.shape, generator=gen, dtype=xb.dtype, device=device) * noise_sigma
                xb = xb + noise

            out = model(xb)

            if task_type == "classification":
                loss = criterion(out, yb)
                pred = out.argmax(dim=1)
                total_loss += loss.item() * xb.size(0)
                total_n += xb.size(0)
                all_true.append(yb.detach().cpu().numpy())
                all_pred.append(pred.detach().cpu().numpy())
            else:
                out = out.view(-1, 1)
                yb = yb.view(-1, 1)
                loss = criterion(out, yb)
                total_loss += loss.item() * xb.size(0)
                total_n += xb.size(0)
                all_true.append(yb.detach().cpu().numpy().reshape(-1))
                all_pred.append(out.detach().cpu().numpy().reshape(-1))

    metrics = {"loss": total_loss / max(total_n, 1)}

    if task_type == "classification":
        y_true = np.concatenate(all_true)
        y_pred = np.concatenate(all_pred)
        metrics["acc"] = float((y_true == y_pred).mean())
    else:
        y_true = np.concatenate(all_true)
        y_pred = np.concatenate(all_pred)
        metrics["mse"] = float(np.mean((y_true - y_pred) ** 2))
        metrics["mae"] = float(np.mean(np.abs(y_true - y_pred)))
        metrics["r2"] = float(r2_score(y_true, y_pred))

    return metrics


def dead_unit_rate(model, loader, hidden_dim):
    model.eval()
    sums = [
        torch.zeros(hidden_dim, device=device),
        torch.zeros(hidden_dim, device=device),
    ]
    count = 0

    with torch.no_grad():
        for xb, _ in loader:
            xb = xb.to(device)
            _, (h1, h2) = model(xb, return_hidden=True)
            sums[0] += h1.abs().sum(dim=0)
            sums[1] += h2.abs().sum(dim=0)
            count += xb.size(0)

    dead_rates = []
    for s in sums:
        mean_abs = (s / max(count, 1)).detach().cpu()
        dead_rates.append(float((mean_abs < THRESH_DEAD).float().mean().item()))
    return float(np.mean(dead_rates)), dead_rates


def mixed_activation_mix_stats(model):
    clean_vals = []
    leak_vals = []
    for module in model.modules():
        if isinstance(module, MixedDualPathRattleActivation):
            weights = torch.softmax(module.mix_logits.detach().cpu(), dim=0)
            clean_vals.append(float(weights[0]))
            leak_vals.append(float(weights[1]))
    if not clean_vals:
        return None
    return float(np.mean(clean_vals)), float(np.mean(leak_vals))


def train_model(model, train_loader, val_loader, task_type, max_epochs):
    criterion = nn.CrossEntropyLoss() if task_type == "classification" else nn.MSELoss()
    opt = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)

    best_state = copy.deepcopy(model.state_dict())
    best_val_loss = float("inf")
    best_epoch = 0
    wait = 0
    history = []

    for epoch in range(1, max_epochs + 1):
        model.train()
        train_loss = 0.0
        train_n = 0

        for xb, yb in train_loader:
            xb = xb.to(device)
            yb = yb.to(device)

            opt.zero_grad()
            out = model(xb)

            if task_type == "classification":
                loss = criterion(out, yb)
            else:
                loss = criterion(out.view(-1, 1), yb.view(-1, 1))

            loss.backward()
            opt.step()

            train_loss += loss.item() * xb.size(0)
            train_n += xb.size(0)

        train_loss /= max(train_n, 1)
        val_metrics = evaluate_model(model, val_loader, task_type)
        val_loss = val_metrics["loss"]

        history.append({
            "epoch": epoch,
            "train_loss": train_loss,
            "val_loss": val_loss,
            **val_metrics,
        })

        if val_loss < best_val_loss - 1e-6:
            best_val_loss = val_loss
            best_state = copy.deepcopy(model.state_dict())
            best_epoch = epoch
            wait = 0
        else:
            wait += 1

        if wait >= PATIENCE:
            break

    model.load_state_dict(best_state)
    return history, best_epoch, best_val_loss


# ----------------------------
# Main stress test loop
# ----------------------------
results = []
start_time = time.time()

for seed in SEEDS:
    for task_name, cfg in TASKS.items():
        set_seed(seed)

        X, y = cfg["builder"](seed)
        task_type = cfg["kind"]

        X_train, X_val, X_test, y_train, y_val, y_test = split_and_scale(X, y, task_type, seed)
        train_loader, val_loader, test_loader = make_loaders(
            X_train, y_train, X_val, y_val, X_test, y_test, task_type
        )

        input_dim = X_train.shape[1]
        output_dim = cfg["num_classes"] if task_type == "classification" else 1

        for act_name in ACTIVATIONS:
            set_seed(seed)

            model = MLP(input_dim, HIDDEN_DIM, output_dim, act_name).to(device)
            t0 = time.time()
            history, best_epoch, best_val_loss = train_model(
                model, train_loader, val_loader, task_type, max_epochs=cfg["epochs"]
            )
            train_time = time.time() - t0

            train_metrics = evaluate_model(model, train_loader, task_type, noise_sigma=0.0, noise_seed=seed)
            val_metrics = evaluate_model(model, val_loader, task_type, noise_sigma=0.0, noise_seed=seed)
            test_metrics = evaluate_model(model, test_loader, task_type, noise_sigma=0.0, noise_seed=seed)

            dead_avg, dead_layers = dead_unit_rate(model, train_loader, HIDDEN_DIM)
            mix_stats = mixed_activation_mix_stats(model)

            row = {
                "seed": seed,
                "task": task_name,
                "kind": task_type,
                "activation": act_name,
                "epochs_ran": len(history),
                "best_epoch": best_epoch,
                "best_val_loss": best_val_loss,
                "train_time_sec": train_time,
                "dead_rate_avg": dead_avg,
                "dead_rate_layer1": dead_layers[0],
                "dead_rate_layer2": dead_layers[1],
                "train_loss": train_metrics["loss"],
                "val_loss": val_metrics["loss"],
                "test_loss": test_metrics["loss"],
                "mix_clean_mean": np.nan,
                "mix_leak_mean": np.nan,
            }

            if mix_stats is not None:
                row["mix_clean_mean"], row["mix_leak_mean"] = mix_stats

            if task_type == "classification":
                row["train_acc"] = train_metrics["acc"]
                row["val_acc"] = val_metrics["acc"]
                row["test_acc"] = test_metrics["acc"]

                for sigma in cfg["noise_levels"]:
                    noisy_metrics = evaluate_model(
                        model, test_loader, task_type,
                        noise_sigma=sigma,
                        noise_seed=seed + int(sigma * 1000) + 17
                    )
                    row[f"test_acc_noise_{sigma_tag(sigma)}"] = noisy_metrics["acc"]
            else:
                row["train_mse"] = train_metrics["mse"]
                row["val_mse"] = val_metrics["mse"]
                row["test_mse"] = test_metrics["mse"]
                row["train_mae"] = train_metrics["mae"]
                row["val_mae"] = val_metrics["mae"]
                row["test_mae"] = test_metrics["mae"]
                row["test_r2"] = test_metrics["r2"]

                for sigma in cfg["noise_levels"]:
                    noisy_metrics = evaluate_model(
                        model, test_loader, task_type,
                        noise_sigma=sigma,
                        noise_seed=seed + int(sigma * 1000) + 17
                    )
                    row[f"test_r2_noise_{sigma_tag(sigma)}"] = noisy_metrics["r2"]
                    row[f"test_mse_noise_{sigma_tag(sigma)}"] = noisy_metrics["mse"]

            results.append(row)

            extra = ""
            if mix_stats is not None:
                extra = f" mix={mix_stats[0]:.3f}/{mix_stats[1]:.3f}"

            print(
                f"[seed {seed} | {task_name:15s} | {act_name:20s}] "
                f"best_epoch={best_epoch:02d} "
                f"val_loss={best_val_loss:.4f} "
                f"test_loss={test_metrics['loss']:.4f} "
                f"dead={dead_avg:.3f} "
                f"time={train_time:.1f}s{extra}"
            )

            del model
            if device.type == "cuda":
                torch.cuda.empty_cache()

results_df = pd.DataFrame(results)
print("\nTotal runtime (min):", round((time.time() - start_time) / 60.0, 2))
print("\nRaw results sample:")
display(results_df.head())

# ----------------------------
# Summaries
# ----------------------------
pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 180)

for task_name, cfg in TASKS.items():
    print("\n" + "=" * 90)
    print("TASK:", task_name, "|", cfg["kind"])
    sub = results_df[results_df["task"] == task_name].copy()

    if cfg["kind"] == "classification":
        cols = ["test_acc", "dead_rate_avg", "best_val_loss", "epochs_ran", "train_time_sec"]
        summary = sub.groupby("activation")[cols].agg(["mean", "std"]).round(4)
        display(summary)

        print("\nNoisy test accuracy:")
        noise_cols = [f"test_acc_noise_{sigma_tag(s)}" for s in cfg["noise_levels"]]
        noise_summary = sub.groupby("activation")[noise_cols].agg(["mean", "std"]).round(4)
        display(noise_summary)

        print("\nLearned mix stats (only for mixed_dual_path_rattle):")
        if "mixed_dual_path_rattle" in sub["activation"].values:
            mix_summary = sub[sub["activation"] == "mixed_dual_path_rattle"][["mix_clean_mean", "mix_leak_mean"]].agg(["mean", "std"]).round(4)
            display(mix_summary)

        ranking = sub.groupby("activation")["test_acc"].mean().sort_values(ascending=False)
        print("\nMean clean test accuracy ranking:")
        print(ranking)

    else:
        cols = ["test_r2", "test_mse", "test_mae", "dead_rate_avg", "best_val_loss", "epochs_ran", "train_time_sec"]
        summary = sub.groupby("activation")[cols].agg(["mean", "std"]).round(4)
        display(summary)

        print("\nNoisy test R2:")
        noise_cols = [f"test_r2_noise_{sigma_tag(s)}" for s in cfg["noise_levels"]]
        noise_summary = sub.groupby("activation")[noise_cols].agg(["mean", "std"]).round(4)
        display(noise_summary)

        print("\nLearned mix stats (only for mixed_dual_path_rattle):")
        if "mixed_dual_path_rattle" in sub["activation"].values:
            mix_summary = sub[sub["activation"] == "mixed_dual_path_rattle"][["mix_clean_mean", "mix_leak_mean"]].agg(["mean", "std"]).round(4)
            display(mix_summary)

        ranking = sub.groupby("activation")["test_r2"].mean().sort_values(ascending=False)
        print("\nMean clean test R2 ranking:")
        print(ranking)

print("\nDone.")

import copy
import time
import random
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import TensorDataset, DataLoader
from sklearn.datasets import make_moons, make_circles, load_digits
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import r2_score
from IPython.display import display
import matplotlib.pyplot as plt

# ----------------------------
# Repro + device
# ----------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("device:", device)

torch.backends.cudnn.benchmark = False

SEEDS = [0, 1, 2]   # keep small for probing; increase later if needed
BATCH_SIZE = 256
HIDDEN_DIM = 64
LR = 1e-3
WEIGHT_DECAY = 1e-4
PATIENCE = 6
THRESH_DEAD = 1e-4

NOISE_LEVELS_CLASS = [0.0, 0.1, 0.25]
NOISE_LEVELS_REG = [0.0, 0.05, 0.15]


def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def sigma_tag(sigma: float) -> str:
    return str(sigma).replace(".", "p")


# ----------------------------
# Mixed Dual-Path Rattle (winner)
# ----------------------------
class MixedDualPathRattleActivation(nn.Module):
    """
    Clean path + leak path + learnable mixing.
    The model learns how much to trust each path.
    """
    def __init__(self, init_a=0.5, init_b=-1.0, init_lambda=0.1, init_mix_clean=1.5, init_mix_leak=-1.5):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(float(init_a)))
        self.b = nn.Parameter(torch.tensor(float(init_b)))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(float(init_lambda))))
        self.mix_logits = nn.Parameter(torch.tensor([float(init_mix_clean), float(init_mix_leak)]))

        # initialize stats with the same keys collect_probe_stats expects
        self.last_stats = {
            "a_mean": 0.0,
            "b_mean": 0.0,
            "lambda_mean": 0.0,
            "mix_clean_mean": 0.0,
            "mix_leak_mean": 0.0,
            "clean_mean": 0.0,
            "leak_mean": 0.0,
            "alpha_mean": 0.0,
            "pressure_mean": 0.0,
        }

    def forward(self, x, mode="full"):
        clean = F.relu(x)

        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        leak = lam * alpha * torch.tanh(x)

        weights = torch.softmax(self.mix_logits, dim=0)
        wc = weights[0]
        wl = weights[1]

        if mode == "full":
            y = wc * clean + wl * leak
        elif mode == "sum":
            y = clean + leak
        elif mode == "clean_only":
            y = clean
        elif mode == "leak_only":
            y = leak
        elif mode == "weighted_clean_only":
            y = wc * clean
        elif mode == "weighted_leak_only":
            y = wl * leak
        else:
            raise ValueError(f"Unknown mode: {mode}")

        # store stats for probing
        self.last_stats = {
            "a_mean": float(self.a.detach().cpu()),
            "b_mean": float(self.b.detach().cpu()),
            "lambda_mean": float(lam.detach().cpu()),
            "mix_clean_mean": float(wc.detach().cpu()),
            "mix_leak_mean": float(wl.detach().cpu()),
            "clean_mean": float(clean.detach().mean().cpu()),
            "leak_mean": float(leak.detach().mean().cpu()),
            "alpha_mean": float(alpha.detach().mean().cpu()),
            "pressure_mean": float(pressure.detach().mean().cpu()),
        }
        return y


# ----------------------------
# Model
# ----------------------------
class MixedPathMLP(nn.Module):
    def __init__(self, input_dim, hidden_dim, output_dim):
        super().__init__()
        self.fc1 = nn.Linear(input_dim, hidden_dim)
        self.act1 = MixedDualPathRattleActivation()
        self.fc2 = nn.Linear(hidden_dim, hidden_dim)
        self.act2 = MixedDualPathRattleActivation()
        self.out = nn.Linear(hidden_dim, output_dim)

    def forward(self, x, mode="full", return_hidden=False):
        h1 = self.act1(self.fc1(x), mode=mode)
        h2 = self.act2(self.fc2(h1), mode=mode)
        out = self.out(h2)
        if return_hidden:
            return out, (h1, h2)
        return out

    def mixed_modules(self):
        for m in self.modules():
            if isinstance(m, MixedDualPathRattleActivation):
                yield m


# ----------------------------
# Data generation
# ----------------------------
def make_xor(n=4000, seed=0):
    rng = np.random.default_rng(seed)
    X = rng.uniform(-1.5, 1.5, size=(n, 2)).astype(np.float32)
    y = ((X[:, 0] > 0) ^ (X[:, 1] > 0)).astype(np.int64)
    flip = rng.random(n) < 0.05
    y[flip] = 1 - y[flip]
    return X, y


def make_sine_regression(n=4000, seed=0):
    rng = np.random.default_rng(seed)
    x = rng.uniform(-4.0, 4.0, size=(n, 1)).astype(np.float32)
    y = (np.sin(3.0 * x[:, 0]) + 0.3 * x[:, 0] + rng.normal(0.0, 0.15, size=n)).astype(np.float32)
    return x, y.reshape(-1, 1)


def load_digits_data():
    digits = load_digits()
    X = digits.data.astype(np.float32)
    y = digits.target.astype(np.int64)
    return X, y


def split_and_scale(X, y, task_type, seed):
    if task_type == "classification":
        X_temp, X_test, y_temp, y_test = train_test_split(
            X, y, test_size=0.2, random_state=seed, stratify=y
        )
        X_train, X_val, y_train, y_val = train_test_split(
            X_temp, y_temp, test_size=0.25, random_state=seed, stratify=y_temp
        )
    else:
        X_temp, X_test, y_temp, y_test = train_test_split(
            X, y, test_size=0.2, random_state=seed
        )
        X_train, X_val, y_train, y_val = train_test_split(
            X_temp, y_temp, test_size=0.25, random_state=seed
        )

    scaler = StandardScaler()
    X_train = scaler.fit_transform(X_train).astype(np.float32)
    X_val = scaler.transform(X_val).astype(np.float32)
    X_test = scaler.transform(X_test).astype(np.float32)

    if task_type == "classification":
        y_train = y_train.astype(np.int64)
        y_val = y_val.astype(np.int64)
        y_test = y_test.astype(np.int64)
    else:
        y_train = y_train.astype(np.float32)
        y_val = y_val.astype(np.float32)
        y_test = y_test.astype(np.float32)

    return X_train, X_val, X_test, y_train, y_val, y_test


def make_loaders(X_train, y_train, X_val, y_val, X_test, y_test, task_type):
    if task_type == "classification":
        y_train_t = torch.tensor(y_train, dtype=torch.long)
        y_val_t = torch.tensor(y_val, dtype=torch.long)
        y_test_t = torch.tensor(y_test, dtype=torch.long)
    else:
        y_train_t = torch.tensor(y_train, dtype=torch.float32)
        y_val_t = torch.tensor(y_val, dtype=torch.float32)
        y_test_t = torch.tensor(y_test, dtype=torch.float32)

    train_ds = TensorDataset(torch.tensor(X_train, dtype=torch.float32), y_train_t)
    val_ds = TensorDataset(torch.tensor(X_val, dtype=torch.float32), y_val_t)
    test_ds = TensorDataset(torch.tensor(X_test, dtype=torch.float32), y_test_t)

    train_loader = DataLoader(train_ds, batch_size=BATCH_SIZE, shuffle=True, drop_last=False)
    val_loader = DataLoader(val_ds, batch_size=BATCH_SIZE, shuffle=False, drop_last=False)
    test_loader = DataLoader(test_ds, batch_size=BATCH_SIZE, shuffle=False, drop_last=False)
    return train_loader, val_loader, test_loader


TASKS = {
    "xor": {
        "kind": "classification",
        "builder": lambda seed: make_xor(n=4000, seed=seed),
        "epochs": 40,
        "num_classes": 2,
        "noise_levels": NOISE_LEVELS_CLASS,
    },
    "moons": {
        "kind": "classification",
        "builder": lambda seed: make_moons(n_samples=4000, noise=0.25, random_state=seed),
        "epochs": 40,
        "num_classes": 2,
        "noise_levels": NOISE_LEVELS_CLASS,
    },
    "circles": {
        "kind": "classification",
        "builder": lambda seed: make_circles(n_samples=4000, factor=0.5, noise=0.15, random_state=seed),
        "epochs": 40,
        "num_classes": 2,
        "noise_levels": NOISE_LEVELS_CLASS,
    },
    "digits": {
        "kind": "classification",
        "builder": lambda seed: load_digits_data(),
        "epochs": 50,
        "num_classes": 10,
        "noise_levels": [0.0, 0.2, 0.5],
    },
    "sine_regression": {
        "kind": "regression",
        "builder": lambda seed: make_sine_regression(n=4000, seed=seed),
        "epochs": 50,
        "num_classes": 1,
        "noise_levels": NOISE_LEVELS_REG,
    },
}


# ----------------------------
# Evaluation helpers
# ----------------------------
def evaluate_model(model, loader, task_type, mode="full", noise_sigma=0.0, noise_seed=0):
    model.eval()
    criterion = nn.CrossEntropyLoss() if task_type == "classification" else nn.MSELoss()

    total_loss = 0.0
    total_n = 0
    all_true = []
    all_pred = []

    gen = torch.Generator(device=device)
    gen.manual_seed(int(noise_seed))

    with torch.no_grad():
        for xb, yb in loader:
            xb = xb.to(device)
            yb = yb.to(device)

            if noise_sigma > 0:
                noise = torch.randn(xb.shape, generator=gen, dtype=xb.dtype, device=device) * noise_sigma
                xb = xb + noise

            out = model(xb, mode=mode)

            if task_type == "classification":
                loss = criterion(out, yb)
                pred = out.argmax(dim=1)
                total_loss += loss.item() * xb.size(0)
                total_n += xb.size(0)
                all_true.append(yb.detach().cpu().numpy())
                all_pred.append(pred.detach().cpu().numpy())
            else:
                out = out.view(-1, 1)
                yb = yb.view(-1, 1)
                loss = criterion(out, yb)
                total_loss += loss.item() * xb.size(0)
                total_n += xb.size(0)
                all_true.append(yb.detach().cpu().numpy().reshape(-1))
                all_pred.append(out.detach().cpu().numpy().reshape(-1))

    metrics = {"loss": total_loss / max(total_n, 1)}

    if task_type == "classification":
        y_true = np.concatenate(all_true)
        y_pred = np.concatenate(all_pred)
        metrics["acc"] = float((y_true == y_pred).mean())
    else:
        y_true = np.concatenate(all_true)
        y_pred = np.concatenate(all_pred)
        metrics["mse"] = float(np.mean((y_true - y_pred) ** 2))
        metrics["mae"] = float(np.mean(np.abs(y_true - y_pred)))
        metrics["r2"] = float(r2_score(y_true, y_pred))

    return metrics


def dead_unit_rate(model, loader, hidden_dim):
    model.eval()
    sums = [torch.zeros(hidden_dim, device=device), torch.zeros(hidden_dim, device=device)]
    count = 0

    with torch.no_grad():
        for xb, _ in loader:
            xb = xb.to(device)
            _, (h1, h2) = model(xb, mode="full", return_hidden=True)
            sums[0] += h1.abs().sum(dim=0)
            sums[1] += h2.abs().sum(dim=0)
            count += xb.size(0)

    dead_rates = []
    for s in sums:
        mean_abs = (s / max(count, 1)).detach().cpu()
        dead_rates.append(float((mean_abs < THRESH_DEAD).float().mean().item()))
    return float(np.mean(dead_rates)), dead_rates


def collect_probe_stats(model):
    """
    Average the stored stats across all mixed activations in the model.
    """
    stats = {
        "a_mean": [],
        "b_mean": [],
        "lambda_mean": [],
        "mix_clean_mean": [],
        "mix_leak_mean": [],
        "clean_mean": [],
        "leak_mean": [],
        "alpha_mean": [],
        "pressure_mean": [],
    }
    for m in model.mixed_modules():
        ls = m.last_stats
        for k in stats.keys():
            stats[k].append(ls.get(k, 0.0))

    return {k: float(np.mean(v)) for k, v in stats.items()}


def train_model(model, train_loader, val_loader, task_type, max_epochs):
    criterion = nn.CrossEntropyLoss() if task_type == "classification" else nn.MSELoss()
    opt = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)

    best_state = copy.deepcopy(model.state_dict())
    best_val_loss = float("inf")
    best_epoch = 0
    wait = 0
    history = []

    probe_x, _ = next(iter(val_loader))
    probe_x = probe_x.to(device)

    for epoch in range(1, max_epochs + 1):
        model.train()
        train_loss = 0.0
        train_n = 0

        for xb, yb in train_loader:
            xb = xb.to(device)
            yb = yb.to(device)

            opt.zero_grad()
            out = model(xb, mode="full")

            if task_type == "classification":
                loss = criterion(out, yb)
            else:
                loss = criterion(out.view(-1, 1), yb.view(-1, 1))

            loss.backward()
            opt.step()

            train_loss += loss.item() * xb.size(0)
            train_n += xb.size(0)

        train_loss /= max(train_n, 1)
        val_full = evaluate_model(model, val_loader, task_type, mode="full")
        val_loss = val_full["loss"]

        # probe current parameter/path statistics after the epoch
        with torch.no_grad():
            _ = model(probe_x, mode="full")
        probe_stats = collect_probe_stats(model)

        history.append({
            "epoch": epoch,
            "train_loss": train_loss,
            "val_loss": val_loss,
            **val_full,
            **probe_stats,
        })

        if val_loss < best_val_loss - 1e-6:
            best_val_loss = val_loss
            best_state = copy.deepcopy(model.state_dict())
            best_epoch = epoch
            wait = 0
        else:
            wait += 1

        if wait >= PATIENCE:
            break

    model.load_state_dict(best_state)
    return history, best_epoch, best_val_loss


# ----------------------------
# Main experiment
# ----------------------------
results = []
trajectories = []
start_time = time.time()

for seed in SEEDS:
    for task_name, cfg in TASKS.items():
        set_seed(seed)

        X, y = cfg["builder"](seed)
        task_type = cfg["kind"]

        X_train, X_val, X_test, y_train, y_val, y_test = split_and_scale(X, y, task_type, seed)
        train_loader, val_loader, test_loader = make_loaders(
            X_train, y_train, X_val, y_val, X_test, y_test, task_type
        )

        input_dim = X_train.shape[1]
        output_dim = cfg["num_classes"] if task_type == "classification" else 1

        model = MixedPathMLP(input_dim, HIDDEN_DIM, output_dim).to(device)

        t0 = time.time()
        history, best_epoch, best_val_loss = train_model(
            model, train_loader, val_loader, task_type, max_epochs=cfg["epochs"]
        )
        train_time = time.time() - t0

        # save epoch trajectory
        for row in history:
            row_out = {
                "seed": seed,
                "task": task_name,
                **row,
            }
            trajectories.append(row_out)

        # final probe stats
        with torch.no_grad():
            probe_x, _ = next(iter(val_loader))
            probe_x = probe_x.to(device)
            _ = model(probe_x, mode="full")
        final_stats = collect_probe_stats(model)

        # evaluate modes to see whether leak helps or not
        mode_list = ["full", "sum", "clean_only", "leak_only", "weighted_clean_only", "weighted_leak_only"]
        mode_metrics = {}
        for mode in mode_list:
            mode_metrics[mode] = evaluate_model(model, test_loader, task_type, mode=mode)

        dead_avg, dead_layers = dead_unit_rate(model, train_loader, HIDDEN_DIM)

        row = {
            "seed": seed,
            "task": task_name,
            "kind": task_type,
            "epochs_ran": len(history),
            "best_epoch": best_epoch,
            "best_val_loss": best_val_loss,
            "train_time_sec": train_time,
            "dead_rate_avg": dead_avg,
            "dead_rate_layer1": dead_layers[0],
            "dead_rate_layer2": dead_layers[1],

            "a_mean": final_stats["a_mean"],
            "b_mean": final_stats["b_mean"],
            "lambda_mean": final_stats["lambda_mean"],
            "mix_clean_mean": final_stats["mix_clean_mean"],
            "mix_leak_mean": final_stats["mix_leak_mean"],
            "clean_mean": final_stats["clean_mean"],
            "leak_mean": final_stats["leak_mean"],
            "alpha_mean": final_stats["alpha_mean"],
            "pressure_mean": final_stats["pressure_mean"],
        }

        if task_type == "classification":
            row["train_acc"] = evaluate_model(model, train_loader, task_type, mode="full")["acc"]
            row["val_acc"] = evaluate_model(model, val_loader, task_type, mode="full")["acc"]
            row["test_acc_full"] = mode_metrics["full"]["acc"]
            row["test_acc_sum"] = mode_metrics["sum"]["acc"]
            row["test_acc_clean_only"] = mode_metrics["clean_only"]["acc"]
            row["test_acc_leak_only"] = mode_metrics["leak_only"]["acc"]
            row["test_acc_weighted_clean_only"] = mode_metrics["weighted_clean_only"]["acc"]
            row["test_acc_weighted_leak_only"] = mode_metrics["weighted_leak_only"]["acc"]

            for sigma in cfg["noise_levels"]:
                noisy = evaluate_model(
                    model, test_loader, task_type, mode="full",
                    noise_sigma=sigma, noise_seed=seed + int(sigma * 1000) + 17
                )
                row[f"test_acc_noise_{sigma_tag(sigma)}"] = noisy["acc"]
        else:
            train_m = evaluate_model(model, train_loader, task_type, mode="full")
            val_m = evaluate_model(model, val_loader, task_type, mode="full")
            row["train_r2"] = train_m["r2"]
            row["val_r2"] = val_m["r2"]

            row["test_r2_full"] = mode_metrics["full"]["r2"]
            row["test_r2_sum"] = mode_metrics["sum"]["r2"]
            row["test_r2_clean_only"] = mode_metrics["clean_only"]["r2"]
            row["test_r2_leak_only"] = mode_metrics["leak_only"]["r2"]
            row["test_r2_weighted_clean_only"] = mode_metrics["weighted_clean_only"]["r2"]
            row["test_r2_weighted_leak_only"] = mode_metrics["weighted_leak_only"]["r2"]

            row["test_mse_full"] = mode_metrics["full"]["mse"]
            row["test_mse_sum"] = mode_metrics["sum"]["mse"]
            row["test_mse_clean_only"] = mode_metrics["clean_only"]["mse"]
            row["test_mse_leak_only"] = mode_metrics["leak_only"]["mse"]

            row["test_mae_full"] = mode_metrics["full"]["mae"]
            row["test_mae_sum"] = mode_metrics["sum"]["mae"]
            row["test_mae_clean_only"] = mode_metrics["clean_only"]["mae"]
            row["test_mae_leak_only"] = mode_metrics["leak_only"]["mae"]

            for sigma in cfg["noise_levels"]:
                noisy = evaluate_model(
                    model, test_loader, task_type, mode="full",
                    noise_sigma=sigma, noise_seed=seed + int(sigma * 1000) + 17
                )
                row[f"test_r2_noise_{sigma_tag(sigma)}"] = noisy["r2"]
                row[f"test_mse_noise_{sigma_tag(sigma)}"] = noisy["mse"]

        results.append(row)

        if task_type == "classification":
            print(
                f"[seed {seed} | {task_name:15s}] "
                f"best_epoch={best_epoch:02d} "
                f"val_loss={best_val_loss:.4f} "
                f"test_acc(full)={mode_metrics['full']['acc']:.4f} "
                f"clean_only={mode_metrics['clean_only']['acc']:.4f} "
                f"leak_only={mode_metrics['leak_only']['acc']:.4f} "
                f"mix={final_stats['mix_clean_mean']:.3f}/{final_stats['mix_leak_mean']:.3f} "
                f"time={train_time:.1f}s"
            )
        else:
            print(
                f"[seed {seed} | {task_name:15s}] "
                f"best_epoch={best_epoch:02d} "
                f"val_loss={best_val_loss:.4f} "
                f"test_r2(full)={mode_metrics['full']['r2']:.4f} "
                f"clean_only={mode_metrics['clean_only']['r2']:.4f} "
                f"leak_only={mode_metrics['leak_only']['r2']:.4f} "
                f"mix={final_stats['mix_clean_mean']:.3f}/{final_stats['mix_leak_mean']:.3f} "
                f"time={train_time:.1f}s"
            )

        del model
        if device.type == "cuda":
            torch.cuda.empty_cache()

results_df = pd.DataFrame(results)
traj_df = pd.DataFrame(trajectories)

print("\nTotal runtime (min):", round((time.time() - start_time) / 60.0, 2))
print("\nResults sample:")
display(results_df.head())

