import torch
import torch.nn as nn
import torch.nn.functional as F
import numpy as np
from sklearn.datasets import load_breast_cancer
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("device:", device)

# ----------------------------
# Activation
# ----------------------------
class MixedDualPathRattleActivation(nn.Module):
    def __init__(self):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(0.5))
        self.b = nn.Parameter(torch.tensor(-1.0))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(0.1)))
        self.mix_logits = nn.Parameter(torch.tensor([1.5, -1.5]))
        self.last_stats = {}

    def forward(self, x, mode="full"):
        clean = F.relu(x)

        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        leak = lam * alpha * torch.tanh(x)

        weights = torch.softmax(self.mix_logits, dim=0)
        wc, wl = weights

        if mode == "full":
            y = wc * clean + wl * leak
        elif mode == "clean_only":
            y = clean
        elif mode == "leak_only":
            y = leak
        else:
            y = clean + leak

        self.last_stats = {
            "mix_clean": float(wc.detach()),
            "mix_leak": float(wl.detach()),
            "lambda": float(lam.detach()),
            "alpha": float(alpha.mean().detach())
        }
        return y

# ----------------------------
# Model
# ----------------------------
class Model(nn.Module):
    def __init__(self, in_dim):
        super().__init__()
        self.fc1 = nn.Linear(in_dim, 64)
        self.act1 = MixedDualPathRattleActivation()
        self.fc2 = nn.Linear(64, 64)
        self.act2 = MixedDualPathRattleActivation()
        self.out = nn.Linear(64, 2)

    def forward(self, x, mode="full"):
        x = self.act1(self.fc1(x), mode)
        x = self.act2(self.fc2(x), mode)
        return self.out(x)

    def get_stats(self):
        s1 = self.act1.last_stats
        s2 = self.act2.last_stats
        return {
            "mix_clean": (s1["mix_clean"] + s2["mix_clean"]) / 2,
            "mix_leak": (s1["mix_leak"] + s2["mix_leak"]) / 2,
            "lambda": (s1["lambda"] + s2["lambda"]) / 2,
            "alpha": (s1["alpha"] + s2["alpha"]) / 2,
        }

# ----------------------------
# Data (REAL dataset)
# ----------------------------
data = load_breast_cancer()
X = data.data.astype(np.float32)
y = data.target.astype(np.int64)

scaler = StandardScaler()
X = scaler.fit_transform(X)

X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2)

X_train = torch.tensor(X_train).to(device)
y_train = torch.tensor(y_train).to(device)
X_test = torch.tensor(X_test).to(device)
y_test = torch.tensor(y_test).to(device)

# ----------------------------
# Train
# ----------------------------
model = Model(X.shape[1]).to(device)
opt = torch.optim.Adam(model.parameters(), lr=1e-3)
loss_fn = nn.CrossEntropyLoss()

for epoch in range(30):
    model.train()
    opt.zero_grad()

    out = model(X_train)
    loss = loss_fn(out, y_train)
    loss.backward()
    opt.step()

    # stats
    with torch.no_grad():
        _ = model(X_train)
        stats = model.get_stats()

    print(f"epoch {epoch:02d} | loss {loss.item():.4f} | mix {stats['mix_clean']:.3f}/{stats['mix_leak']:.3f}")

# ----------------------------
# Evaluation
# ----------------------------
def eval_mode(mode):
    model.eval()
    with torch.no_grad():
        pred = model(X_test, mode).argmax(1)
        acc = (pred == y_test).float().mean().item()
    return acc

print("\nFINAL RESULTS")
print("full       :", eval_mode("full"))
print("clean_only :", eval_mode("clean_only"))
print("leak_only  :", eval_mode("leak_only"))

import torch
import torch.nn as nn
import torch.nn.functional as F
import numpy as np
from sklearn.datasets import load_breast_cancer
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("device:", device)

# ----------------------------
# Activation
# ----------------------------
class MixedDualPathRattleActivation(nn.Module):
    def __init__(self):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(0.5))
        self.b = nn.Parameter(torch.tensor(-1.0))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(0.1)))
        self.mix_logits = nn.Parameter(torch.tensor([1.5, -1.5]))
        self.last_stats = {}

    def forward(self, x, mode="full"):
        clean = F.relu(x)

        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        leak = lam * alpha * torch.tanh(x)

        weights = torch.softmax(self.mix_logits, dim=0)
        # FORCE leak to not vanish
        min_leak = 0.2   # 👈 key idea
        wc = weights[0] * (1 - min_leak)
        wl = weights[1] * (1 - min_leak) + min_leak

        if mode == "full":
            y = wc * clean + wl * leak
        elif mode == "clean_only":
            y = clean
        elif mode == "leak_only":
            y = leak
        else:
            y = clean + leak

        self.last_stats = {
            "mix_clean": float(wc.detach()),
            "mix_leak": float(wl.detach()),
            "lambda": float(lam.detach()),
            "alpha": float(alpha.mean().detach())
        }
        return y

# ----------------------------
# Model
# ----------------------------
class Model(nn.Module):
    def __init__(self, in_dim):
        super().__init__()
        self.fc1 = nn.Linear(in_dim, 64)
        self.act1 = MixedDualPathRattleActivation()
        self.fc2 = nn.Linear(64, 64)
        self.act2 = MixedDualPathRattleActivation()
        self.out = nn.Linear(64, 2)

    def forward(self, x, mode="full"):
        x = self.act1(self.fc1(x), mode)
        x = self.act2(self.fc2(x), mode)
        return self.out(x)

    def get_stats(self):
        s1 = self.act1.last_stats
        s2 = self.act2.last_stats
        return {
            "mix_clean": (s1["mix_clean"] + s2["mix_clean"]) / 2,
            "mix_leak": (s1["mix_leak"] + s2["mix_leak"]) / 2,
            "lambda": (s1["lambda"] + s2["lambda"]) / 2,
            "alpha": (s1["alpha"] + s2["alpha"]) / 2,
        }

# ----------------------------
# Data (REAL dataset)
# ----------------------------
data = load_breast_cancer()
X = data.data.astype(np.float32)
y = data.target.astype(np.int64)

scaler = StandardScaler()
X = scaler.fit_transform(X)

X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2)

X_train = torch.tensor(X_train).to(device)
y_train = torch.tensor(y_train).to(device)
X_test = torch.tensor(X_test).to(device)
y_test = torch.tensor(y_test).to(device)

# ----------------------------
# Train
# ----------------------------
model = Model(X.shape[1]).to(device)
opt = torch.optim.Adam(model.parameters(), lr=1e-3)
loss_fn = nn.CrossEntropyLoss()

for epoch in range(30):
    model.train()
    opt.zero_grad()

    out = model(X_train)
    loss = loss_fn(out, y_train)
    loss.backward()
    opt.step()

    # stats
    with torch.no_grad():
        _ = model(X_train)
        stats = model.get_stats()

    print(f"epoch {epoch:02d} | loss {loss.item():.4f} | mix {stats['mix_clean']:.3f}/{stats['mix_leak']:.3f}")

# ----------------------------
# Evaluation
# ----------------------------
def eval_mode(mode):
    model.eval()
    with torch.no_grad():
        pred = model(X_test, mode).argmax(1)
        acc = (pred == y_test).float().mean().item()
    return acc

print("\nFINAL RESULTS")
print("full       :", eval_mode("full"))
print("clean_only :", eval_mode("clean_only"))
print("leak_only  :", eval_mode("leak_only"))

