import torch
import torch.nn as nn
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import pandas as pd
import numpy as np
import random
import time

device = torch.device("cpu")

def set_seed(seed):
    torch.manual_seed(seed)
    np.random.seed(seed)
    random.seed(seed)

# -----------------------------
# Mixed Activation
# -----------------------------
class MixedActivation(nn.Module):
    def __init__(self, alpha=0.1):
        super().__init__()
        self.alpha = alpha
    def forward(self, x):
        return torch.where(x >= 0, x, self.alpha * x)

# -----------------------------
# Model (lighter)
# -----------------------------
class SmallCNN(nn.Module):
    def __init__(self, activation="relu"):
        super().__init__()

        def act():
            if activation == "relu":
                return nn.ReLU()
            elif activation == "leaky_relu":
                return nn.LeakyReLU(0.1)
            else:
                return MixedActivation(0.1)

        self.net = nn.Sequential(
            nn.Conv2d(3, 32, 3, padding=1),
            act(),
            nn.MaxPool2d(2),

            nn.Conv2d(32, 64, 3, padding=1),
            act(),
            nn.MaxPool2d(2),

            nn.Flatten(),
            nn.Linear(64*8*8, 128),
            act(),
            nn.Linear(128, 10)
        )

    def forward(self, x):
        return self.net(x)

# -----------------------------
# Dead neurons
# -----------------------------
def compute_dead_rate(model, loader):
    model.eval()
    zeros, total = 0, 0
    with torch.no_grad():
        for x, _ in loader:
            x = x.to(device)
            out = model.net[1](model.net[0](x))
            zeros += (out <= 0).sum().item()
            total += out.numel()
    return zeros / total

# -----------------------------
# Train / Eval
# -----------------------------
def train(model, loader, optimizer, criterion, epoch):
    model.train()
    for i, (x, y) in enumerate(loader):
        x, y = x.to(device), y.to(device)

        optimizer.zero_grad()
        out = model(x)
        loss = criterion(out, y)
        loss.backward()
        optimizer.step()

        if i % 50 == 0:
            print(f"  epoch {epoch} | step {i}")

def evaluate(model, loader):
    model.eval()
    correct, total = 0, 0
    with torch.no_grad():
        for x, y in loader:
            x, y = x.to(device), y.to(device)
            pred = model(x).argmax(1)
            correct += (pred == y).sum().item()
            total += y.size(0)
    return correct / total

# -----------------------------
# Data (20% subset)
# -----------------------------
transform = transforms.ToTensor()

trainset = torchvision.datasets.CIFAR10(root="./data", train=True, download=True, transform=transform)
testset = torchvision.datasets.CIFAR10(root="./data", train=False, download=True, transform=transform)

subset_size = int(0.2 * len(trainset))
indices = list(range(subset_size))
train_subset = torch.utils.data.Subset(trainset, indices)

trainloader = torch.utils.data.DataLoader(train_subset, batch_size=128, shuffle=True)
testloader = torch.utils.data.DataLoader(testset, batch_size=256)

# -----------------------------
# Experiment
# -----------------------------
activations = ["relu", "leaky_relu", "mixed"]
seeds = [0, 1, 2]
epochs = 5

results = []

for act in activations:
    for seed in seeds:
        print(f"\n=== {act} | seed {seed} ===")

        set_seed(seed)
        model = SmallCNN(act).to(device)

        opt = optim.Adam(model.parameters(), lr=1e-3)
        loss_fn = nn.CrossEntropyLoss()

        start = time.time()

        for ep in range(epochs):
            train(model, trainloader, opt, loss_fn, ep)

        acc = evaluate(model, testloader)
        dead = compute_dead_rate(model, trainloader)
        t = time.time() - start

        print(f"FINAL: acc={acc:.4f}, dead={dead:.4f}, time={t:.1f}s")

        results.append({
            "activation": act,
            "seed": seed,
            "accuracy": acc,
            "dead_rate": dead,
            "time": t
        })

# save
df = pd.DataFrame(results)
df.to_csv("fast_results.csv", index=False)

print("\nDONE. Saved fast_results.csv")

