import os
import math
import copy
import time
import random
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torchvision
import torchvision.transforms as T
from torch.utils.data import DataLoader, Subset
from sklearn.model_selection import train_test_split
import matplotlib.pyplot as plt

# ============================================================
# Setup
# ============================================================
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("device:", device)

if device.type == "cuda":
    torch.backends.cudnn.benchmark = True

os.makedirs("outputs", exist_ok=True)

# ============================================================
# Config
# Keep these modest so the sweep stays runnable.
# ============================================================
DATA_ROOT = "./data"

TRAIN_FRAC = 0.25          # fraction of CIFAR-10 train set used for training
VAL_FRAC = 0.10            # validation fraction inside the selected train subset
BATCH_SIZE = 128
NUM_WORKERS = 2 if device.type == "cuda" else 0

MAIN_EPOCHS = 5
SWEEP_EPOCHS = 5

SEEDS = [0, 1, 2]
DEPTHS = [4, 8]            # "deep CNN" sweep
NOISE_LEVELS = [0.0, 0.10, 0.20]

MAIN_ACTIVATIONS = ["relu", "leaky_relu", "mixed"]

# Leak-band sweep
LEAK_SWEEP_DEPTH = 4
LEAK_TARGETS = [0.00, 0.01, 0.05, 0.10, 0.20, 0.50]
LEAK_PENALTY = 0.10        # fixed penalty to hold target band

BASE_CHANNELS = 32
CHANNEL_CAP = 128
THRESH_DEAD = 1e-4

pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 220)

# ============================================================
# Reproducibility
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)

def inv_sigmoid(p: float) -> float:
    p = float(np.clip(p, 1e-4, 1.0 - 1e-4))
    return math.log(p / (1.0 - p))

def noise_tag(sigma: float) -> str:
    return str(sigma).replace(".", "p")

# ============================================================
# Data
# ============================================================
CIFAR_MEAN = (0.4914, 0.4822, 0.4465)
CIFAR_STD = (0.2023, 0.1994, 0.2010)

train_tf = T.Compose([
    T.RandomCrop(32, padding=4),
    T.RandomHorizontalFlip(),
    T.ToTensor(),
    T.Normalize(CIFAR_MEAN, CIFAR_STD),
])

eval_tf = T.Compose([
    T.ToTensor(),
    T.Normalize(CIFAR_MEAN, CIFAR_STD),
])

def build_cifar10_loaders(seed: int, train_frac: float = TRAIN_FRAC, val_frac: float = VAL_FRAC):
    """
    Returns train_loader, val_loader, test_loader.
    Train subset is sampled from the CIFAR-10 training split.
    Validation uses the same selected samples but deterministic transforms.
    """
    base_train_aug = torchvision.datasets.CIFAR10(
        root=DATA_ROOT, train=True, download=True, transform=train_tf
    )
    base_train_eval = torchvision.datasets.CIFAR10(
        root=DATA_ROOT, train=True, download=True, transform=eval_tf
    )
    test_ds = torchvision.datasets.CIFAR10(
        root=DATA_ROOT, train=False, download=True, transform=eval_tf
    )

    targets = np.array(base_train_aug.targets)
    rng = np.random.default_rng(seed)

    subset_size = int(len(base_train_aug) * train_frac)
    subset_indices = rng.choice(len(base_train_aug), size=subset_size, replace=False)

    train_idx, val_idx = train_test_split(
        subset_indices,
        test_size=val_frac,
        random_state=seed,
        stratify=targets[subset_indices],
    )

    train_ds = Subset(base_train_aug, train_idx.tolist())
    val_ds = Subset(base_train_eval, val_idx.tolist())

    pin = device.type == "cuda"

    train_loader = DataLoader(
        train_ds,
        batch_size=BATCH_SIZE,
        shuffle=True,
        num_workers=NUM_WORKERS,
        pin_memory=pin,
        drop_last=False,
    )
    val_loader = DataLoader(
        val_ds,
        batch_size=BATCH_SIZE,
        shuffle=False,
        num_workers=NUM_WORKERS,
        pin_memory=pin,
        drop_last=False,
    )
    test_loader = DataLoader(
        test_ds,
        batch_size=BATCH_SIZE,
        shuffle=False,
        num_workers=NUM_WORKERS,
        pin_memory=pin,
        drop_last=False,
    )
    return train_loader, val_loader, test_loader

# ============================================================
# Activations
# ============================================================
def best_group_count(channels: int) -> int:
    for g in (8, 4, 2, 1):
        if channels % g == 0:
            return g
    return 1

class ReLUAct(nn.Module):
    def forward(self, x, mode="full"):
        return F.relu(x)

class LeakyAct(nn.Module):
    def __init__(self, negative_slope=0.01):
        super().__init__()
        self.negative_slope = negative_slope

    def forward(self, x, mode="full"):
        return F.leaky_relu(x, negative_slope=self.negative_slope)

class MixedDualPathActivation(nn.Module):
    """
    clean path + bounded leak path + learnable per-channel mixing
    full: wc * clean + wl * leak
    clean_only: clean
    leak_only: leak
    sum: clean + leak
    weighted_clean_only: wc * clean
    weighted_leak_only: wl * leak
    """
    def __init__(self, channels, init_a=0.5, init_b=-1.0, init_lambda=0.10):
        super().__init__()
        self.channels = channels
        self.a = nn.Parameter(torch.full((channels,), float(init_a)))
        self.b = nn.Parameter(torch.full((channels,), float(init_b)))
        self.logit_lambda = nn.Parameter(torch.full((channels,), inv_sigmoid(init_lambda)))

        mix_init = torch.empty(channels, 2)
        mix_init[:, 0] = 1.5
        mix_init[:, 1] = -1.5
        self.mix_logits = nn.Parameter(mix_init)

        self.last_stats = {}

    def forward(self, x, mode="full"):
        clean = F.relu(x)

        pressure = x.abs()
        a = self.a.view(1, -1, 1, 1)
        b = self.b.view(1, -1, 1, 1)
        lam = torch.sigmoid(self.logit_lambda).view(1, -1, 1, 1)

        alpha = torch.sigmoid(a * pressure + b)
        leak = lam * alpha * torch.tanh(x)

        weights = torch.softmax(self.mix_logits, dim=1)
        wc = weights[:, 0].view(1, -1, 1, 1)
        wl = weights[:, 1].view(1, -1, 1, 1)

        if mode == "full":
            y = wc * clean + wl * leak
        elif mode == "clean_only":
            y = clean
        elif mode == "leak_only":
            y = leak
        elif mode == "sum":
            y = clean + leak
        elif mode == "weighted_clean_only":
            y = wc * clean
        elif mode == "weighted_leak_only":
            y = wl * leak
        else:
            raise ValueError(f"Unknown mode: {mode}")

        self.last_stats = {
            "mix_clean_mean": float(wc.detach().mean().cpu()),
            "mix_leak_mean": float(wl.detach().mean().cpu()),
            "lambda_mean": float(lam.detach().mean().cpu()),
            "alpha_mean": float(alpha.detach().mean().cpu()),
            "pressure_mean": float(pressure.detach().mean().cpu()),
        }
        return y

class ForcedLeakActivation(nn.Module):
    """
    Additive leak variant:
        y = ReLU(x) + w_l * leak(x)

    with leak(x) = lambda * alpha * x
    and w_l held near a target band by a penalty.
    """
    def __init__(self, channels, target_leak=0.05, init_lambda=0.25, init_a=0.5, init_b=-1.0):
        super().__init__()
        self.channels = channels
        self.target_leak = float(target_leak)

        self.a = nn.Parameter(torch.full((channels,), float(init_a)))
        self.b = nn.Parameter(torch.full((channels,), float(init_b)))
        self.logit_lambda = nn.Parameter(torch.full((channels,), inv_sigmoid(init_lambda)))

        init_t = float(np.clip(target_leak, 1e-4, 1.0 - 1e-4))
        self.mix_logits = nn.Parameter(torch.full((channels,), inv_sigmoid(init_t)))

        self.last_stats = {}

    def forward(self, x, mode="full"):
        clean = F.relu(x)

        pressure = x.abs()
        a = self.a.view(1, -1, 1, 1)
        b = self.b.view(1, -1, 1, 1)
        lam = torch.sigmoid(self.logit_lambda).view(1, -1, 1, 1)

        alpha = torch.sigmoid(a * pressure + b)
        leak = lam * alpha * x  # stronger additive leak than tanh-bounded version

        wl = torch.sigmoid(self.mix_logits).view(1, -1, 1, 1)

        if mode == "full" or mode == "sum":
            y = clean + wl * leak
        elif mode == "clean_only":
            y = clean
        elif mode == "leak_only":
            y = leak
        else:
            raise ValueError(f"Unknown mode: {mode}")

        self.last_stats = {
            "wl_mean": float(wl.detach().mean().cpu()),
            "lambda_mean": float(lam.detach().mean().cpu()),
            "alpha_mean": float(alpha.detach().mean().cpu()),
            "pressure_mean": float(pressure.detach().mean().cpu()),
        }
        return y

    def leak_penalty(self, strength: float):
        wl_mean = torch.sigmoid(self.mix_logits).mean()
        target = torch.tensor(self.target_leak, device=wl_mean.device, dtype=wl_mean.dtype)
        return strength * (wl_mean - target) ** 2

def make_activation(name: str, channels: int, target_leak: float = 0.05):
    if name == "relu":
        return ReLUAct()
    if name == "leaky_relu":
        return LeakyAct(negative_slope=0.01)
    if name == "mixed":
        return MixedDualPathActivation(channels=channels, init_lambda=0.10)
    if name == "forced":
        return ForcedLeakActivation(channels=channels, target_leak=target_leak, init_lambda=0.25)
    raise ValueError(f"Unknown activation: {name}")

# ============================================================
# Model
# ============================================================
class ConvBlock(nn.Module):
    def __init__(self, in_ch, out_ch, activation_name, target_leak=0.05):
        super().__init__()
        self.conv = nn.Conv2d(in_ch, out_ch, kernel_size=3, padding=1, bias=False)
        self.norm = nn.GroupNorm(best_group_count(out_ch), out_ch)
        self.act = make_activation(activation_name, out_ch, target_leak=target_leak)

    def forward(self, x, mode="full"):
        x = self.conv(x)
        x = self.norm(x)
        x = self.act(x, mode=mode)
        return x

class DeepCIFARNet(nn.Module):
    def __init__(self, depth=4, activation_name="relu", target_leak=0.05):
        super().__init__()
        self.depth = depth
        self.activation_name = activation_name
        self.target_leak = target_leak

        layers = []
        in_ch = 3
        for i in range(depth):
            out_ch = BASE_CHANNELS * (2 ** (i // 2))
            out_ch = min(out_ch, CHANNEL_CAP)
            layers.append(ConvBlock(in_ch, out_ch, activation_name, target_leak=target_leak))
            if (i + 1) % 2 == 0:
                layers.append(nn.MaxPool2d(2))
            in_ch = out_ch

        self.layers = nn.ModuleList(layers)
        self.final_pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Linear(in_ch, 10)

        self.act_modules = [m.act for m in self.layers if isinstance(m, ConvBlock)]

    def forward(self, x, mode="full", return_acts=False):
        acts = []
        for layer in self.layers:
            if isinstance(layer, ConvBlock):
                x = layer(x, mode=mode)
                acts.append(x)
            else:
                x = layer(x)
        x = self.final_pool(x).flatten(1)
        logits = self.classifier(x)
        if return_acts:
            return logits, acts
        return logits

    def activation_penalty(self, strength: float):
        if strength <= 0:
            return torch.tensor(0.0, device=next(self.parameters()).device)

        penalties = []
        for m in self.act_modules:
            if hasattr(m, "leak_penalty"):
                penalties.append(m.leak_penalty(strength))
        if not penalties:
            return torch.tensor(0.0, device=next(self.parameters()).device)
        return sum(penalties) / len(penalties)

# ============================================================
# Helpers
# ============================================================
def evaluate(model, loader, mode="full", noise_sigma=0.0):
    model.eval()
    criterion = nn.CrossEntropyLoss()
    total_loss = 0.0
    total_n = 0
    correct = 0

    gen = torch.Generator(device=device)
    gen.manual_seed(123456)

    with torch.no_grad():
        for xb, yb in loader:
            xb = xb.to(device, non_blocking=True)
            yb = yb.to(device, non_blocking=True)

            if noise_sigma > 0:
                noise = torch.randn(
                    xb.shape,
                    generator=gen,
                    device=device,
                    dtype=xb.dtype,
                ) * noise_sigma
                xb = xb + noise

            logits = model(xb, mode=mode)
            loss = criterion(logits, yb)

            total_loss += loss.item() * xb.size(0)
            total_n += xb.size(0)
            correct += (logits.argmax(dim=1) == yb).sum().item()

    return {
        "loss": total_loss / max(total_n, 1),
        "acc": correct / max(total_n, 1),
    }

def compute_dead_rate(model, loader, mode="full"):
    """
    Mean fraction of channels whose mean absolute activation is below THRESH_DEAD.
    Averaged over all activation blocks.
    """
    model.eval()
    channel_sums = None
    total_n = 0

    with torch.no_grad():
        for xb, _ in loader:
            xb = xb.to(device, non_blocking=True)
            _, acts = model(xb, mode=mode, return_acts=True)

            if channel_sums is None:
                channel_sums = [torch.zeros(a.shape[1], device=device) for a in acts]

            for i, a in enumerate(acts):
                # mean over batch and spatial dims -> [channels]
                mean_abs_per_channel = a.abs().mean(dim=(0, 2, 3))
                channel_sums[i] += mean_abs_per_channel * xb.size(0)

            total_n += xb.size(0)

    layer_rates = []
    for s in channel_sums:
        mean_abs = s / max(total_n, 1)
        layer_rates.append(float((mean_abs < THRESH_DEAD).float().mean().item()))

    return float(np.mean(layer_rates)), layer_rates

def collect_activation_stats(model, loader):
    """
    Run one batch through the model in full mode and average the last_stats
    from all custom activation modules.
    """
    model.eval()
    sample_x, _ = next(iter(loader))
    sample_x = sample_x.to(device, non_blocking=True)

    with torch.no_grad():
        _ = model(sample_x, mode="full")

    stats_acc = {}
    counts = {}
    for m in model.modules():
        if hasattr(m, "last_stats") and isinstance(m.last_stats, dict) and len(m.last_stats) > 0:
            for k, v in m.last_stats.items():
                stats_acc[k] = stats_acc.get(k, 0.0) + float(v)
                counts[k] = counts.get(k, 0) + 1

    return {k: stats_acc[k] / counts[k] for k in stats_acc}

def train_model(model, train_loader, val_loader, epochs=5, lr=1e-3, weight_decay=1e-4, penalty_strength=0.0):
    criterion = nn.CrossEntropyLoss()
    optimizer = torch.optim.AdamW(model.parameters(), lr=lr, weight_decay=weight_decay)

    best_state = copy.deepcopy(model.state_dict())
    best_val_loss = float("inf")
    best_epoch = -1
    history = []

    for epoch in range(epochs):
        model.train()
        train_loss = 0.0
        train_n = 0

        for xb, yb in train_loader:
            xb = xb.to(device, non_blocking=True)
            yb = yb.to(device, non_blocking=True)

            optimizer.zero_grad(set_to_none=True)
            logits = model(xb, mode="full")
            loss = criterion(logits, yb)

            penalty = model.activation_penalty(penalty_strength)
            loss = loss + penalty

            loss.backward()
            optimizer.step()

            train_loss += loss.item() * xb.size(0)
            train_n += xb.size(0)

        train_loss /= max(train_n, 1)
        val_metrics = evaluate(model, val_loader, mode="full", noise_sigma=0.0)

        history.append({
            "epoch": epoch,
            "train_loss": train_loss,
            "val_loss": val_metrics["loss"],
            "val_acc": val_metrics["acc"],
        })

        if val_metrics["loss"] < best_val_loss - 1e-6:
            best_val_loss = val_metrics["loss"]
            best_epoch = epoch
            best_state = copy.deepcopy(model.state_dict())

    model.load_state_dict(best_state)
    return history, best_epoch, best_val_loss

# ============================================================
# Main benchmark: CIFAR-10 depth sweep + noise sweep + seed sweep + activations
# ============================================================
main_rows = []
start_time = time.time()

print("\nRunning main CIFAR-10 benchmark...\n")

for depth in DEPTHS:
    for seed in SEEDS:
        set_seed(seed)
        train_loader, val_loader, test_loader = build_cifar10_loaders(seed)

        for act_name in MAIN_ACTIVATIONS:
            set_seed(seed)
            model = DeepCIFARNet(depth=depth, activation_name=act_name, target_leak=0.05).to(device)

            t0 = time.time()
            history, best_epoch, best_val_loss = train_model(
                model,
                train_loader,
                val_loader,
                epochs=MAIN_EPOCHS,
                lr=1e-3,
                weight_decay=1e-4,
                penalty_strength=0.0,
            )
            train_time = time.time() - t0

            test_full = evaluate(model, test_loader, mode="full", noise_sigma=0.0)
            dead_avg, dead_layers = compute_dead_rate(model, val_loader, mode="full")
            stats = collect_activation_stats(model, val_loader)

            row = {
                "dataset": "cifar10",
                "depth": depth,
                "seed": seed,
                "activation": act_name,
                "epochs_ran": len(history),
                "best_epoch": best_epoch,
                "best_val_loss": best_val_loss,
                "train_time_sec": train_time,
                "dead_rate_avg": dead_avg,
                "dead_rate_layer1": dead_layers[0] if len(dead_layers) > 0 else np.nan,
                "dead_rate_layer2": dead_layers[1] if len(dead_layers) > 1 else np.nan,
                "test_acc_full": test_full["acc"],
                "test_loss_full": test_full["loss"],
            }

            for sigma in NOISE_LEVELS:
                noisy = evaluate(model, test_loader, mode="full", noise_sigma=sigma)
                row[f"test_acc_noise_{noise_tag(sigma)}"] = noisy["acc"]
                row[f"test_loss_noise_{noise_tag(sigma)}"] = noisy["loss"]

            if act_name == "mixed":
                row["test_acc_clean_only"] = evaluate(model, test_loader, mode="clean_only", noise_sigma=0.0)["acc"]
                row["test_acc_leak_only"] = evaluate(model, test_loader, mode="leak_only", noise_sigma=0.0)["acc"]
                row["test_acc_sum"] = evaluate(model, test_loader, mode="sum", noise_sigma=0.0)["acc"]
                row["test_acc_weighted_clean_only"] = evaluate(model, test_loader, mode="weighted_clean_only", noise_sigma=0.0)["acc"]
                row["test_acc_weighted_leak_only"] = evaluate(model, test_loader, mode="weighted_leak_only", noise_sigma=0.0)["acc"]
            else:
                row["test_acc_clean_only"] = np.nan
                row["test_acc_leak_only"] = np.nan
                row["test_acc_sum"] = np.nan
                row["test_acc_weighted_clean_only"] = np.nan
                row["test_acc_weighted_leak_only"] = np.nan

            for k in ["mix_clean_mean", "mix_leak_mean", "wl_mean", "lambda_mean", "alpha_mean", "pressure_mean"]:
                row[k] = stats.get(k, np.nan)

            main_rows.append(row)

            print(
                f"[main | d={depth} | s={seed} | {act_name:10s}] "
                f"acc={test_full['acc']:.4f} dead={dead_avg:.4f} "
                f"best_val={best_val_loss:.4f} time={train_time:.1f}s"
            )

main_df = pd.DataFrame(main_rows)
main_df.to_csv("outputs/cifar10_main_benchmark.csv", index=False)

print("\nMain benchmark runtime (min):", round((time.time() - start_time) / 60.0, 2))
print("\n================ MAIN SUMMARY ================")

main_summary = main_df.groupby(["depth", "activation"])[
    ["test_acc_full", "dead_rate_avg", "best_val_loss", "train_time_sec"]
].agg(["mean", "std"]).round(4)
print(main_summary)

print("\nCustom activation stats:")
stats_cols = [c for c in ["mix_clean_mean", "mix_leak_mean", "wl_mean", "lambda_mean", "alpha_mean", "pressure_mean"] if c in main_df.columns]
print(main_df.groupby("activation")[stats_cols].agg(["mean", "std"]).round(4))

print("\nMixed-mode diagnostics:")
mixed_diag_cols = ["test_acc_full", "test_acc_clean_only", "test_acc_leak_only", "test_acc_sum", "test_acc_weighted_clean_only", "test_acc_weighted_leak_only"]
