print(mixed_diag)

# Plot: main benchmark clean accuracy vs depth
plt.figure(figsize=(8, 5))
for act_name in MAIN_ACTIVATIONS:
    sub = main_df[main_df["activation"] == act_name].groupby("depth")["test_acc_full"].agg(["mean", "std"]).reset_index()
    plt.errorbar(sub["depth"], sub["mean"], yerr=sub["std"], marker="o", capsize=4, label=act_name)
plt.xlabel("Depth")
plt.ylabel("Test Accuracy")
