# ============================================================
# Leak-band sweep: forced additive leak
# ============================================================
leak_rows = []
print("\nRunning leak-band sweep...\n")

for depth in [LEAK_SWEEP_DEPTH]:
    for seed in SEEDS:
        set_seed(seed)
