import os
import copy
import time
import random
from pathlib import Path

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torchvision
import torchvision.transforms as transforms
from sklearn.model_selection import train_test_split
import matplotlib.pyplot as plt

# =========================
# Config
# =========================
SEEDS = [0, 1, 2]
DEPTH = 25                 # 25 hidden layers, no residuals
HIDDEN_DIM = 128
EPOCHS = 5
BATCH_SIZE = 256
LR = 1e-3
WEIGHT_DECAY = 1e-4
TRAIN_FRACTION = 0.5       # increase to 1.0 if you have extra time
VAL_FRACTION = 0.1         # validation split from the selected train subset
THRESH_DEAD = 1e-4

ACTIVATIONS = ["relu", "leaky_relu", "mixed"]

OUTDIR = Path("deep_stress_outputs")
OUTDIR.mkdir(parents=True, exist_ok=True)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("device:", device)

if device.type == "cuda":
    torch.backends.cudnn.benchmark = True

# =========================
# Reproducibility
# =========================
def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# =========================
# Data
# =========================
def build_cifar10_loaders(seed: int):
    transform = transforms.Compose([
        transforms.ToTensor(),
        transforms.Normalize(
            mean=(0.4914, 0.4822, 0.4465),
            std=(0.2470, 0.2435, 0.2616),
        ),
    ])

    train_full = torchvision.datasets.CIFAR10(
        root="./data", train=True, download=True, transform=transform
    )
    test_ds = torchvision.datasets.CIFAR10(
        root="./data", train=False, download=True, transform=transform
    )

    y = np.array(train_full.targets)
    all_idx = np.arange(len(y))

    # stratified subset of the original train set
    subset_idx, _ = train_test_split(
        all_idx,
        train_size=TRAIN_FRACTION,
        random_state=seed,
        stratify=y,
    )
    subset_y = y[subset_idx]

    train_idx, val_idx = train_test_split(
        subset_idx,
        test_size=VAL_FRACTION,
        random_state=seed,
        stratify=subset_y,
    )

    train_ds = torch.utils.data.Subset(train_full, train_idx.tolist())
    val_ds = torch.utils.data.Subset(train_full, val_idx.tolist())

    num_workers = 2 if device.type == "cuda" else 0
    pin_memory = device.type == "cuda"

    train_loader = torch.utils.data.DataLoader(
        train_ds,
        batch_size=BATCH_SIZE,
        shuffle=True,
        num_workers=num_workers,
        pin_memory=pin_memory,
        drop_last=False,
    )
    val_loader = torch.utils.data.DataLoader(
        val_ds,
        batch_size=BATCH_SIZE,
        shuffle=False,
        num_workers=num_workers,
        pin_memory=pin_memory,
        drop_last=False,
    )
    test_loader = torch.utils.data.DataLoader(
        test_ds,
        batch_size=BATCH_SIZE,
        shuffle=False,
        num_workers=num_workers,
        pin_memory=pin_memory,
        drop_last=False,
    )

    return train_loader, val_loader, test_loader

# =========================
# Activations
# =========================
class ReLUAct(nn.Module):
    def forward(self, x, mode="full"):
        return F.relu(x)

class LeakyAct(nn.Module):
    def __init__(self, negative_slope=0.01):
        super().__init__()
        self.negative_slope = negative_slope

    def forward(self, x, mode="full"):
        return F.leaky_relu(x, negative_slope=self.negative_slope)

class MixedDualPathActivation(nn.Module):
    """
    Per-layer mixed dual-path activation:
      clean(x) = ReLU(x)
      leak(x)  = lambda * alpha(|x|) * tanh(x)
      y = wc * clean + wl * leak
    """
    def __init__(self, dim, init_a=0.5, init_b=-1.0, init_lambda=0.1, init_mix_clean=1.5, init_mix_leak=-1.5):
        super().__init__()
        self.a = nn.Parameter(torch.full((dim,), float(init_a)))
        self.b = nn.Parameter(torch.full((dim,), float(init_b)))
        self.logit_lambda = nn.Parameter(torch.full((dim,), float(torch.logit(torch.tensor(init_lambda)))))
        self.mix_logits = nn.Parameter(torch.tensor([float(init_mix_clean), float(init_mix_leak)]))

        self.last_stats = {
            "clean_w": 0.0,
            "leak_w": 0.0,
            "lambda": 0.0,
            "alpha": 0.0,
            "pressure": 0.0,
        }

    def forward(self, x, mode="full"):
        clean = F.relu(x)
        pressure = torch.abs(x)

        a = self.a.unsqueeze(0)
        b = self.b.unsqueeze(0)
        lam = torch.sigmoid(self.logit_lambda).unsqueeze(0)

        alpha = torch.sigmoid(a * pressure + b)
        leak = lam * alpha * torch.tanh(x)

        w = torch.softmax(self.mix_logits, dim=0)
        wc, wl = w[0], w[1]

        if mode == "full":
            y = wc * clean + wl * leak
        elif mode == "clean_only":
            y = clean
        elif mode == "leak_only":
            y = leak
        elif mode == "sum":
            y = clean + leak
        elif mode == "weighted_clean_only":
            y = wc * clean
        elif mode == "weighted_leak_only":
            y = wl * leak
        else:
            raise ValueError(f"Unknown mode: {mode}")

        self.last_stats = {
            "clean_w": float(wc.detach().cpu()),
            "leak_w": float(wl.detach().cpu()),
            "lambda": float(lam.mean().detach().cpu()),
            "alpha": float(alpha.mean().detach().cpu()),
            "pressure": float(pressure.mean().detach().cpu()),
        }
        return y

# =========================
# Model
# =========================
class DeepNoResidualMLP(nn.Module):
    def __init__(self, activation_name: str, depth: int = DEPTH, hidden_dim: int = HIDDEN_DIM, num_classes: int = 10):
        super().__init__()
        self.activation_name = activation_name
        self.depth = depth
        self.hidden_dim = hidden_dim

        self.flatten = nn.Flatten()
        self.in_proj = nn.Linear(3 * 32 * 32, hidden_dim)
        self.hidden_layers = nn.ModuleList([nn.Linear(hidden_dim, hidden_dim) for _ in range(depth - 1)])
        self.out = nn.Linear(hidden_dim, num_classes)

        if activation_name == "relu":
            self.acts = nn.ModuleList([ReLUAct() for _ in range(depth)])
        elif activation_name == "leaky_relu":
            self.acts = nn.ModuleList([LeakyAct(negative_slope=0.01) for _ in range(depth)])
        elif activation_name == "mixed":
            self.acts = nn.ModuleList([MixedDualPathActivation(hidden_dim) for _ in range(depth)])
        else:
            raise ValueError(f"Unknown activation: {activation_name}")

        self.apply(self._init_weights)

    @staticmethod
    def _init_weights(m):
        if isinstance(m, nn.Linear):
            nn.init.kaiming_normal_(m.weight, nonlinearity="relu")
            if m.bias is not None:
                nn.init.zeros_(m.bias)

    def forward(self, x, mode="full", return_hiddens=False):
        x = self.flatten(x)
        hiddens = []

        x = self.in_proj(x)
        x = self.acts[0](x, mode=mode)
        hiddens.append(x)

        for i, layer in enumerate(self.hidden_layers, start=1):
            x = layer(x)
            x = self.acts[i](x, mode=mode)
            hiddens.append(x)

        logits = self.out(x)
        if return_hiddens:
            return logits, hiddens
        return logits

    def mixed_modules(self):
        return [m for m in self.acts if isinstance(m, MixedDualPathActivation)]

# =========================
# Evaluation + probing
# =========================
@torch.no_grad()
def evaluate(model, loader, activation_name: str, mode: str = "full"):
    model.eval()
    criterion = nn.CrossEntropyLoss()

    total_loss = 0.0
    total_n = 0
    correct = 0

    for xb, yb in loader:
        xb = xb.to(device, non_blocking=True)
        yb = yb.to(device, non_blocking=True)

        if activation_name == "mixed":
            logits = model(xb, mode=mode)
        else:
            logits = model(xb, mode="full")

        loss = criterion(logits, yb)

        total_loss += loss.item() * xb.size(0)
        total_n += xb.size(0)
        correct += (logits.argmax(dim=1) == yb).sum().item()

    return {
        "loss": total_loss / max(total_n, 1),
        "acc": correct / max(total_n, 1),
    }

@torch.no_grad()
def collect_layerwise_stats(model, loader, activation_name: str):
    model.eval()
    n_layers = model.depth

    sum_abs = [torch.zeros(model.hidden_dim, device=device) for _ in range(n_layers)]
    sample_count = 0

    mixed_lists = {
        "clean_w": [[] for _ in range(n_layers)],
        "leak_w": [[] for _ in range(n_layers)],
        "lambda": [[] for _ in range(n_layers)],
        "alpha": [[] for _ in range(n_layers)],
        "pressure": [[] for _ in range(n_layers)],
    }

    for xb, _ in loader:
        xb = xb.to(device, non_blocking=True)
        _, hiddens = model(xb, mode="full", return_hiddens=True)
        sample_count += xb.size(0)

        for i, h in enumerate(hiddens):
            sum_abs[i] += h.abs().sum(dim=0)

            if activation_name == "mixed":
                st = model.acts[i].last_stats
                for k in mixed_lists:
                    mixed_lists[k][i].append(st[k])

    dead_rates = []
    for s in sum_abs:
        mean_abs = (s / max(sample_count, 1)).detach().cpu()
        dead_rates.append(float((mean_abs < THRESH_DEAD).float().mean().item()))

    if activation_name == "mixed":
        mixed_stats = {}
        for k, per_layer_lists in mixed_lists.items():
            mixed_stats[k] = [float(np.mean(v)) if len(v) > 0 else np.nan for v in per_layer_lists]
    else:
        mixed_stats = None

    return dead_rates, mixed_stats

def train_one_model(seed: int, activation_name: str):
    set_seed(seed)
    train_loader, val_loader, test_loader = build_cifar10_loaders(seed)

    model = DeepNoResidualMLP(activation_name=activation_name).to(device)
    optimizer = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)
    criterion = nn.CrossEntropyLoss()

    best_state = copy.deepcopy(model.state_dict())
    best_val_loss = float("inf")
    best_epoch = -1
    history = []

    start = time.time()

    for epoch in range(EPOCHS):
        model.train()
        running_loss = 0.0
        seen = 0

        for xb, yb in train_loader:
            xb = xb.to(device, non_blocking=True)
            yb = yb.to(device, non_blocking=True)

            optimizer.zero_grad(set_to_none=True)
            logits = model(xb, mode="full")
            loss = criterion(logits, yb)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
            optimizer.step()

            running_loss += loss.item() * xb.size(0)
            seen += xb.size(0)

        train_loss = running_loss / max(seen, 1)
        val_metrics = evaluate(model, val_loader, activation_name, mode="full")

        history.append({
            "seed": seed,
            "activation": activation_name,
            "epoch": epoch,
            "train_loss": train_loss,
            "val_loss": val_metrics["loss"],
            "val_acc": val_metrics["acc"],
        })

        if val_metrics["loss"] < best_val_loss - 1e-6:
            best_val_loss = val_metrics["loss"]
            best_epoch = epoch
            best_state = copy.deepcopy(model.state_dict())

    elapsed = time.time() - start
    model.load_state_dict(best_state)

    test_full = evaluate(model, test_loader, activation_name, mode="full")
    test_modes = {}
    if activation_name == "mixed":
        for mode in ["sum", "clean_only", "leak_only", "weighted_clean_only", "weighted_leak_only"]:
            test_modes[mode] = evaluate(model, test_loader, activation_name, mode=mode)

    dead_rates, mixed_stats = collect_layerwise_stats(model, test_loader, activation_name)

    row = {
        "seed": seed,
        "activation": activation_name,
        "best_epoch": best_epoch,
        "best_val_loss": best_val_loss,
        "train_time_sec": elapsed,
        "test_acc_full": test_full["acc"],
        "test_loss_full": test_full["loss"],
        "dead_rate_avg": float(np.mean(dead_rates)),
        "dead_rate_min": float(np.min(dead_rates)),
        "dead_rate_max": float(np.max(dead_rates)),
    }

    if activation_name == "mixed":
        row.update({
            "test_acc_sum": test_modes["sum"]["acc"],
            "test_acc_clean_only": test_modes["clean_only"]["acc"],
            "test_acc_leak_only": test_modes["leak_only"]["acc"],
            "test_acc_weighted_clean_only": test_modes["weighted_clean_only"]["acc"],
            "test_acc_weighted_leak_only": test_modes["weighted_leak_only"]["acc"],
            "mix_clean_mean": float(np.mean(mixed_stats["clean_w"])),
            "mix_leak_mean": float(np.mean(mixed_stats["leak_w"])),
            "lambda_mean": float(np.mean(mixed_stats["lambda"])),
            "alpha_mean": float(np.mean(mixed_stats["alpha"])),
            "pressure_mean": float(np.mean(mixed_stats["pressure"])),
        })
    else:
        row.update({
            "test_acc_sum": np.nan,
            "test_acc_clean_only": np.nan,
            "test_acc_leak_only": np.nan,
            "test_acc_weighted_clean_only": np.nan,
            "test_acc_weighted_leak_only": np.nan,
            "mix_clean_mean": np.nan,
            "mix_leak_mean": np.nan,
            "lambda_mean": np.nan,
            "alpha_mean": np.nan,
            "pressure_mean": np.nan,
        })

    layer_rows = []
    for layer_idx, dr in enumerate(dead_rates, start=1):
        lr_row = {
            "seed": seed,
            "activation": activation_name,
            "layer": layer_idx,
            "dead_rate": dr,
        }
        if activation_name == "mixed":
            lr_row.update({
                "clean_w": mixed_stats["clean_w"][layer_idx - 1],
                "leak_w": mixed_stats["leak_w"][layer_idx - 1],
                "lambda": mixed_stats["lambda"][layer_idx - 1],
                "alpha": mixed_stats["alpha"][layer_idx - 1],
                "pressure": mixed_stats["pressure"][layer_idx - 1],
            })
        else:
            lr_row.update({
                "clean_w": np.nan,
                "leak_w": np.nan,
                "lambda": np.nan,
                "alpha": np.nan,
                "pressure": np.nan,
            })
        layer_rows.append(lr_row)

    return row, layer_rows, history

# =========================
# Run benchmark
# =========================
results = []
layerwise_rows = []
history_rows = []

print("Running deep 25-layer stress test...\n")

for act in ACTIVATIONS:
    for seed in SEEDS:
        print(f"=== {act} | seed {seed} ===")
        row, layer_rows, hist = train_one_model(seed, act)
        results.append(row)
        layerwise_rows.extend(layer_rows)
        history_rows.extend(hist)

        print(
            f"FINAL: acc={row['test_acc_full']:.4f}, "
            f"dead={row['dead_rate_avg']:.4f}, "
            f"best_val={row['best_val_loss']:.4f}, "
            f"time={row['train_time_sec']:.1f}s"
        )
        if act == "mixed":
            print(
                f"      mix clean/leak = {row['mix_clean_mean']:.3f}/{row['mix_leak_mean']:.3f}, "
                f"lambda={row['lambda_mean']:.3f}, alpha={row['alpha_mean']:.3f}"
            )

results_df = pd.DataFrame(results)
layerwise_df = pd.DataFrame(layerwise_rows)
history_df = pd.DataFrame(history_rows)

results_csv = OUTDIR / "deep_stress_results.csv"
layer_csv = OUTDIR / "deep_stress_layerwise.csv"
history_csv = OUTDIR / "deep_stress_history.csv"

results_df.to_csv(results_csv, index=False)
layerwise_df.to_csv(layer_csv, index=False)
history_df.to_csv(history_csv, index=False)

print("\nSaved:")
print(f" - {results_csv}")
print(f" - {layer_csv}")
print(f" - {history_csv}")

# =========================
# Summary tables
# =========================
pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 200)

print("\n================ OVERALL SUMMARY ================")
summary_cols = ["test_acc_full", "dead_rate_avg", "best_val_loss", "train_time_sec"]
print(results_df.groupby("activation")[summary_cols].agg(["mean", "std"]).round(4))

print("\n================ MIXED DIAGNOSTICS ================")
mixed_df = results_df[results_df["activation"] == "mixed"].copy()
if not mixed_df.empty:
    print(
        mixed_df[[
            "test_acc_full",
            "test_acc_sum",
            "test_acc_clean_only",
            "test_acc_leak_only",
            "mix_clean_mean",
            "mix_leak_mean",
            "lambda_mean",
            "alpha_mean",
            "pressure_mean",
        ]].agg(["mean", "std"]).round(4)
    )

print("\n================ LAYERWISE SUMMARY (MIXED) ================")
if not layerwise_df[layerwise_df["activation"] == "mixed"].empty:
    mixed_layer_summary = layerwise_df[layerwise_df["activation"] == "mixed"].groupby("layer")[[
        "clean_w", "leak_w", "lambda", "alpha", "pressure", "dead_rate"
    ]].agg(["mean", "std"]).round(4)
    print(mixed_layer_summary)

# =========================
# Visualization
# =========================
layers = np.arange(1, DEPTH + 1)
fig, axes = plt.subplots(2, 1, figsize=(12, 10), sharex=True)

# Top: mixed clean vs leak weights across layers
mixed_layers = layerwise_df[layerwise_df["activation"] == "mixed"].groupby("layer").agg(
    clean_mean=("clean_w", "mean"),
    clean_std=("clean_w", "std"),
    leak_mean=("leak_w", "mean"),
    leak_std=("leak_w", "std"),
)

if not mixed_layers.empty:
    cm = mixed_layers["clean_mean"].to_numpy()
    cs = mixed_layers["clean_std"].to_numpy()
    lm = mixed_layers["leak_mean"].to_numpy()
    ls = mixed_layers["leak_std"].to_numpy()

    axes[0].plot(layers, cm, label="clean weight")
    axes[0].fill_between(layers, cm - np.nan_to_num(cs, nan=0.0), cm + np.nan_to_num(cs, nan=0.0), alpha=0.2)
    axes[0].plot(layers, lm, label="leak weight")
    axes[0].fill_between(layers, lm - np.nan_to_num(ls, nan=0.0), lm + np.nan_to_num(ls, nan=0.0), alpha=0.2)

axes[0].set_title("Mixed Dual-Path: layerwise clean vs leak weights")
axes[0].set_ylabel("Mean path weight")
axes[0].legend()
axes[0].grid(True, alpha=0.3)

# Bottom: dead rate per layer for all activations
for act in ACTIVATIONS:
    sub = layerwise_df[layerwise_df["activation"] == act].groupby("layer").agg(
        dead_mean=("dead_rate", "mean"),
        dead_std=("dead_rate", "std"),
    )
    dm = sub["dead_mean"].to_numpy()
    ds = sub["dead_std"].to_numpy()
    axes[1].plot(layers, dm, label=act)
    axes[1].fill_between(layers, dm - np.nan_to_num(ds, nan=0.0), dm + np.nan_to_num(ds, nan=0.0), alpha=0.15)

axes[1].set_title("Dead-unit rate by layer")
axes[1].set_xlabel("Layer")
axes[1].set_ylabel("Dead-unit rate")
axes[1].legend()
axes[1].grid(True, alpha=0.3)

plt.tight_layout()
fig_path = OUTDIR / "deep_stress_layerwise_figure.png"
plt.savefig(fig_path, dpi=200, bbox_inches="tight")
plt.show()

print(f"\nSaved figure: {fig_path}")
print("\nDone.")

import os
import math
import random
import time
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
import matplotlib.pyplot as plt

# ============================================================
# Config
# ============================================================
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("device:", device)

SEEDS = [0, 1, 2]
DEPTHS = [25, 50]          # add 75 later only if 50 is stable
ACTIVATIONS = ["relu", "leaky", "mixed"]
EPOCHS = 3
BATCH_SIZE = 128
LR = 1e-3
WEIGHT_DECAY = 1e-4
TRAIN_FRACTION = 0.25      # subset of CIFAR-10 train set
VAL_FRACTION = 0.10        # of the selected subset
THRESH_DEAD = 1e-4
NUM_WORKERS = 2 if device.type == "cuda" else 0
PIN_MEMORY = device.type == "cuda"
NOISE_SWEEP = [0.0, 0.1, 0.2]   # test-time input noise only

OUTPUT_DIR = "deep_break_outputs"
os.makedirs(OUTPUT_DIR, exist_ok=True)

torch.backends.cudnn.benchmark = True

# CIFAR-10 normalization
CIFAR_MEAN = (0.4914, 0.4822, 0.4465)
CIFAR_STD = (0.2023, 0.1994, 0.2010)

# ============================================================
# Utilities
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)

def grad_norm(model: nn.Module) -> float:
    total_sq = 0.0
    for p in model.parameters():
        if p.grad is not None:
            g = p.grad.detach()
            total_sq += float(g.norm(2).item() ** 2)
    return math.sqrt(total_sq)

def make_pool_positions(depth: int, num_pools: int = 4):
    if depth <= 1 or num_pools <= 0:
        return set()
    # evenly distribute pools through the depth, but never at the ends
    positions = np.linspace(0, depth - 1, num_pools + 2, dtype=int)[1:-1]
    return set(int(p) for p in positions)

def dead_rate_from_tensor(x: torch.Tensor, threshold: float = THRESH_DEAD) -> float:
    """
    x is an activation output tensor, usually [B, C, H, W].
    A channel is considered "dead" if its mean absolute activation over the batch
    and spatial dimensions is below threshold.
    """
    if x is None:
        return float("nan")
    if x.dim() == 4:
        per_channel = x.abs().mean(dim=(0, 2, 3))
    elif x.dim() == 2:
        per_channel = x.abs().mean(dim=0)
    else:
        dims = tuple(range(x.dim() - 1))
        per_channel = x.abs().mean(dim=dims)
    return float((per_channel < threshold).float().mean().item())

# ============================================================
# Activations
# ============================================================
class BaseActivation(nn.Module):
    def __init__(self):
        super().__init__()
        self.last_out = None

    def get_stats(self):
        return {
            "clean_w": float("nan"),
            "leak_w": float("nan"),
            "lambda": float("nan"),
            "alpha_mean": float("nan"),
            "pressure_mean": float("nan"),
        }

class ReLUAct(BaseActivation):
    def forward(self, x):
        y = F.relu(x)
        self.last_out = y.detach()
        return y

class LeakyAct(BaseActivation):
    def __init__(self, negative_slope=0.01):
        super().__init__()
        self.negative_slope = negative_slope

    def forward(self, x):
        y = F.leaky_relu(x, negative_slope=self.negative_slope)
        self.last_out = y.detach()
        return y

class MixedActivation(BaseActivation):
    """
    Clean path + bounded leak path + learnable mixture.
    Per-layer parameters are separate because each activation module is separate.
    """
    def __init__(self):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(0.5))
        self.b = nn.Parameter(torch.tensor(-1.0))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(0.10)))
        self.mix_logits = nn.Parameter(torch.tensor([3.0, -3.0]))  # clean-biased init

        self.last_stats = {
            "clean_w": float("nan"),
            "leak_w": float("nan"),
            "lambda": float("nan"),
            "alpha_mean": float("nan"),
            "pressure_mean": float("nan"),
        }

    def forward(self, x):
        clean = F.relu(x)
        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        leak = lam * alpha * torch.tanh(x)

        w = torch.softmax(self.mix_logits, dim=0)
        y = w[0] * clean + w[1] * leak

        self.last_out = y.detach()
        self.last_stats = {
            "clean_w": float(w[0].detach().cpu()),
            "leak_w": float(w[1].detach().cpu()),
            "lambda": float(lam.detach().cpu()),
            "alpha_mean": float(alpha.detach().mean().cpu()),
            "pressure_mean": float(pressure.detach().mean().cpu()),
        }
        return y

    def get_stats(self):
        return self.last_stats.copy()

# ============================================================
# Deep CNN without residuals
# ============================================================
class DeepCNN(nn.Module):
    def __init__(self, depth=25, activation="relu", width=64, num_pools=4):
        super().__init__()
        self.depth = depth
        self.width = width
        self.activation_name = activation
        self.pool_positions = make_pool_positions(depth, num_pools=num_pools)

        self.convs = nn.ModuleList()
        self.acts = nn.ModuleList()
        in_ch = 3

        for i in range(depth):
            self.convs.append(nn.Conv2d(in_ch, width, kernel_size=3, padding=1))

            if activation == "relu":
                self.acts.append(ReLUAct())
            elif activation == "leaky":
                self.acts.append(LeakyAct(negative_slope=0.01))
            elif activation == "mixed":
                self.acts.append(MixedActivation())
            else:
                raise ValueError(f"Unknown activation: {activation}")

            in_ch = width

        self.pool = nn.MaxPool2d(2)
        self.adapt = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Linear(width, 10)

        self._init_weights()

    def _init_weights(self):
        for m in self.modules():
            if isinstance(m, nn.Conv2d):
                nn.init.kaiming_normal_(m.weight, nonlinearity="relu")
                if m.bias is not None:
                    nn.init.zeros_(m.bias)
            elif isinstance(m, nn.Linear):
                nn.init.kaiming_normal_(m.weight, nonlinearity="linear")
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x):
        for i, (conv, act) in enumerate(zip(self.convs, self.acts)):
            x = conv(x)
            x = act(x)
            if i in self.pool_positions:
                x = self.pool(x)
        x = self.adapt(x)
        x = torch.flatten(x, 1)
        x = self.classifier(x)
        return x

    def mixed_layers(self):
        return [m for m in self.acts if isinstance(m, MixedActivation)]

# ============================================================
# Data
# ============================================================
train_transform = transforms.Compose([
    transforms.RandomCrop(32, padding=4),
    transforms.RandomHorizontalFlip(),
    transforms.ToTensor(),
    transforms.Normalize(CIFAR_MEAN, CIFAR_STD),
])

eval_transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize(CIFAR_MEAN, CIFAR_STD),
])

full_train_aug = torchvision.datasets.CIFAR10(
    root="./data", train=True, download=True, transform=train_transform
)
full_train_eval = torchvision.datasets.CIFAR10(
    root="./data", train=True, download=True, transform=eval_transform
)
test_set = torchvision.datasets.CIFAR10(
    root="./data", train=False, download=True, transform=eval_transform
)

def build_loaders(seed: int, train_fraction: float = TRAIN_FRACTION, val_fraction: float = VAL_FRACTION):
    n_total = len(full_train_eval)
    n_select = int(n_total * train_fraction)

    g = torch.Generator().manual_seed(seed)
    perm = torch.randperm(n_total, generator=g).tolist()
    selected = perm[:n_select]

    n_val = max(1, int(len(selected) * val_fraction))
    val_idx = selected[:n_val]
    train_idx = selected[n_val:]

    train_ds = torch.utils.data.Subset(full_train_aug, train_idx)
    val_ds = torch.utils.data.Subset(full_train_eval, val_idx)

    train_loader = torch.utils.data.DataLoader(
        train_ds, batch_size=BATCH_SIZE, shuffle=True,
        num_workers=NUM_WORKERS, pin_memory=PIN_MEMORY, drop_last=False
    )
    val_loader = torch.utils.data.DataLoader(
        val_ds, batch_size=BATCH_SIZE, shuffle=False,
        num_workers=NUM_WORKERS, pin_memory=PIN_MEMORY, drop_last=False
    )
    test_loader = torch.utils.data.DataLoader(
        test_set, batch_size=BATCH_SIZE * 2, shuffle=False,
        num_workers=NUM_WORKERS, pin_memory=PIN_MEMORY, drop_last=False
    )
    return train_loader, val_loader, test_loader

# ============================================================
# Train / eval
# ============================================================
def train_one_epoch(model, loader, optimizer, loss_fn):
    model.train()
    running_loss = 0.0
    running_gn = []
    n_seen = 0

    for xb, yb in loader:
        xb = xb.to(device, non_blocking=True)
        yb = yb.to(device, non_blocking=True)

        optimizer.zero_grad(set_to_none=True)
        out = model(xb)
        loss = loss_fn(out, yb)

        if not torch.isfinite(loss):
            return float("nan"), float("nan")

        loss.backward()
        running_gn.append(grad_norm(model))
        optimizer.step()

        running_loss += loss.item() * xb.size(0)
        n_seen += xb.size(0)

    return running_loss / max(n_seen, 1), float(np.mean(running_gn)) if running_gn else float("nan")

@torch.no_grad()
def evaluate(model, loader, noise_std=0.0):
    model.eval()
    loss_fn = nn.CrossEntropyLoss()
    total_loss = 0.0
    correct = 0
    total = 0

    for xb, yb in loader:
        xb = xb.to(device, non_blocking=True)
        yb = yb.to(device, non_blocking=True)

        if noise_std > 0:
            xb = xb + torch.randn_like(xb) * noise_std

        out = model(xb)
        loss = loss_fn(out, yb)

        total_loss += loss.item() * xb.size(0)
        pred = out.argmax(dim=1)
        correct += (pred == yb).sum().item()
        total += yb.size(0)

    return {
        "loss": total_loss / max(total, 1),
        "acc": correct / max(total, 1),
    }

@torch.no_grad()
def collect_layerwise_diagnostics(model, probe_loader, threshold=THRESH_DEAD):
    """
    Runs one probe batch through the model and collects per-layer stats.
    """
    model.eval()
    xb, _ = next(iter(probe_loader))
    xb = xb.to(device, non_blocking=True)

    _ = model(xb)

    rows = []
    for layer_id, act in enumerate(model.acts, start=1):
        out = act.last_out
        stats = act.get_stats()
        rows.append({
            "layer": layer_id,
            "dead_rate": dead_rate_from_tensor(out, threshold=threshold),
            "clean_w": stats["clean_w"],
            "leak_w": stats["leak_w"],
            "lambda": stats["lambda"],
            "alpha_mean": stats["alpha_mean"],
            "pressure_mean": stats["pressure_mean"],
        })
    return rows

# ============================================================
# Main experiment
# ============================================================
results = []
layerwise_rows = []

start_all = time.time()
print("\nRunning deep breaking-point stress test...")

for depth in DEPTHS:
    for act_name in ACTIVATIONS:
        for seed in SEEDS:
            print(f"\n=== depth={depth} | activation={act_name} | seed={seed} ===")
            set_seed(seed)

            train_loader, val_loader, test_loader = build_loaders(seed)
            model = DeepCNN(depth=depth, activation=act_name, width=64, num_pools=4).to(device)

            optimizer = optim.AdamW(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)
            loss_fn = nn.CrossEntropyLoss()

            best_state = None
            best_val_loss = float("inf")
            best_epoch = -1
            epoch_grad_norms = []
            epoch_train_losses = []

            t0 = time.time()

            for epoch in range(1, EPOCHS + 1):
                train_loss, gnorm = train_one_epoch(model, train_loader, optimizer, loss_fn)
                if not np.isfinite(train_loss):
                    print(f"  epoch {epoch}: non-finite loss, stopping early")
                    break

                val_m = evaluate(model, val_loader, noise_std=0.0)
                epoch_train_losses.append(train_loss)
                epoch_grad_norms.append(gnorm)

                if val_m["loss"] < best_val_loss - 1e-6:
                    best_val_loss = val_m["loss"]
                    best_epoch = epoch
                    best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}

                print(f"  epoch {epoch:02d} | train_loss={train_loss:.4f} | val_loss={val_m['loss']:.4f} | grad_norm={gnorm:.2f}")

            if best_state is not None:
                model.load_state_dict(best_state)

            test_clean = evaluate(model, test_loader, noise_std=0.0)
            noisy_metrics = {f"test_acc_noise_{str(s).replace('.', 'p')}": evaluate(model, test_loader, noise_std=s)["acc"]
                             for s in NOISE_SWEEP if s > 0}

            # One probe pass for layerwise diagnostics
            probe_loader = torch.utils.data.DataLoader(
                torch.utils.data.Subset(full_train_eval, list(range(0, min(1024, len(full_train_eval))))),
                batch_size=256, shuffle=False, num_workers=0
            )
            layer_rows = collect_layerwise_diagnostics(model, probe_loader, threshold=THRESH_DEAD)

            layer_dead_vals = [r["dead_rate"] for r in layer_rows if np.isfinite(r["dead_rate"])]
            layer_dead_mean = float(np.mean(layer_dead_vals)) if layer_dead_vals else float("nan")

            run_time = time.time() - t0

            mixed_layers = model.mixed_layers()
            mixed_diag = {}
            if act_name == "mixed":
                clean_ws = [m.get_stats()["clean_w"] for m in mixed_layers]
                leak_ws = [m.get_stats()["leak_w"] for m in mixed_layers]
                lambdas = [m.get_stats()["lambda"] for m in mixed_layers]
                alphas = [m.get_stats()["alpha_mean"] for m in mixed_layers]
                pressures = [m.get_stats()["pressure_mean"] for m in mixed_layers]

                mixed_diag = {
                    "mix_clean_mean": float(np.mean(clean_ws)),
                    "mix_leak_mean": float(np.mean(leak_ws)),
                    "lambda_mean": float(np.mean(lambdas)),
                    "alpha_mean": float(np.mean(alphas)),
                    "pressure_mean": float(np.mean(pressures)),
                }

                for r in layer_rows:
                    r.update({
                        "depth": depth,
                        "activation": act_name,
                        "seed": seed,
                    })
                    layerwise_rows.append(r)

            row = {
                "depth": depth,
                "activation": act_name,
                "seed": seed,
                "epochs_ran": len(epoch_train_losses),
                "best_epoch": best_epoch,
                "best_val_loss": best_val_loss,
                "test_acc_full": test_clean["acc"],
                "test_loss_full": test_clean["loss"],
                "dead_rate_avg": layer_dead_mean,
                "train_time_sec": run_time,
                "grad_norm_mean": float(np.mean(epoch_grad_norms)) if epoch_grad_norms else float("nan"),
                "grad_norm_max": float(np.max(epoch_grad_norms)) if epoch_grad_norms else float("nan"),
            }
            row.update(noisy_metrics)
            row.update(mixed_diag)

            # Diagnostics specific to the mixed model
            if act_name == "mixed":
                # test clean-only / leak-only / sum on the same trained model
                # by temporarily using the module structure
                # We reuse the same modules; "mode" is not needed because the model is hard-coded mixed.
                # For reference, we use the mixed model as trained and evaluate alternative paths manually.
                def eval_mixed_mode(mode):
                    model.eval()
                    correct = 0
                    total = 0
                    with torch.no_grad():
                        for xb, yb in test_loader:
                            xb = xb.to(device, non_blocking=True)
                            yb = yb.to(device, non_blocking=True)

                            # Run layer-by-layer with overridden mode
                            x = xb
                            for conv, act in zip(model.convs, model.acts):
                                x = conv(x)
                                if mode == "clean_only":
                                    if isinstance(act, MixedActivation):
                                        x = F.relu(x)
                                    elif isinstance(act, LeakyAct):
                                        x = F.leaky_relu(x, negative_slope=0.01)
                                    else:
                                        x = F.relu(x)
                                elif mode == "leak_only":
                                    if isinstance(act, MixedActivation):
                                        pressure = torch.abs(x)
                                        alpha = torch.sigmoid(act.a * pressure + act.b)
                                        lam = torch.sigmoid(act.logit_lambda)
                                        x = lam * alpha * torch.tanh(x)
                                    elif isinstance(act, LeakyAct):
                                        x = F.leaky_relu(x, negative_slope=0.01)
                                    else:
                                        x = F.relu(x)
                                elif mode == "sum":
                                    if isinstance(act, MixedActivation):
                                        pressure = torch.abs(x)
                                        alpha = torch.sigmoid(act.a * pressure + act.b)
                                        lam = torch.sigmoid(act.logit_lambda)
                                        x = F.relu(x) + lam * alpha * torch.tanh(x)
                                    elif isinstance(act, LeakyAct):
                                        x = F.leaky_relu(x, negative_slope=0.01)
                                    else:
                                        x = F.relu(x)
                                else:
                                    raise ValueError(mode)

                                if conv in [model.convs[i] for i in model.pool_positions]:
                                    x = model.pool(x)

                            x = model.adapt(x)
                            x = torch.flatten(x, 1)
                            logits = model.classifier(x)
                            pred = logits.argmax(dim=1)
                            correct += (pred == yb).sum().item()
                            total += yb.size(0)
                    return correct / max(total, 1)

                row["test_acc_clean_only"] = eval_mixed_mode("clean_only")
                row["test_acc_leak_only"] = eval_mixed_mode("leak_only")
                row["test_acc_sum"] = eval_mixed_mode("sum")

                # weighted path diagnostics
                mixed_layers = model.mixed_layers()
                row["mix_clean_mean"] = float(np.mean([m.get_stats()["clean_w"] for m in mixed_layers]))
                row["mix_leak_mean"] = float(np.mean([m.get_stats()["leak_w"] for m in mixed_layers]))
                row["lambda_mean"] = float(np.mean([m.get_stats()["lambda"] for m in mixed_layers]))
                row["alpha_mean"] = float(np.mean([m.get_stats()["alpha_mean"] for m in mixed_layers]))
                row["pressure_mean"] = float(np.mean([m.get_stats()["pressure_mean"] for m in mixed_layers]))

            results.append(row)

            print(
                f"FINAL: acc={row['test_acc_full']:.4f}, dead={row['dead_rate_avg']:.4f}, "
                f"best_val={row['best_val_loss']:.4f}, time={run_time:.1f}s"
            )
            if act_name == "mixed":
                print(
                    f"      mix clean/leak = {row['mix_clean_mean']:.3f}/{row['mix_leak_mean']:.3f}, "
                    f"lambda={row['lambda_mean']:.3f}, alpha={row['alpha_mean']:.3f}"
                )

# ============================================================
# Save results
# ============================================================
results_df = pd.DataFrame(results)
layerwise_df = pd.DataFrame(layerwise_rows)

results_csv = os.path.join(OUTPUT_DIR, "deep_stress_results.csv")
layerwise_csv = os.path.join(OUTPUT_DIR, "deep_stress_layerwise.csv")
results_df.to_csv(results_csv, index=False)
layerwise_df.to_csv(layerwise_csv, index=False)

print("\nSaved:")
print(" -", results_csv)
print(" -", layerwise_csv)

# ============================================================
