# (b) Dead rate vs LR
ax = axes[0, 1]
for variant in order:
    sub = lr_df[lr_df["variant"] == variant].groupby("lr")["best_val_acc"].agg(["mean", "std"]).reset_index()
    dsub = lr_df[lr_df["variant"] == variant].groupby("lr")["train_time_sec"].agg(["mean", "std"]).reset_index()
    dead_sub = lr_df[lr_df["variant"] == variant].groupby("lr")["test_acc_full"].agg(["mean", "std"]).reset_index()
    # dead rate is stored only in the raw df as a row-level metric? In this run we did not store it explicitly.
