import os
import math
import random
import time
from copy import deepcopy

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset, DataLoader
import torchvision
import torchvision.transforms as transforms
from sklearn.model_selection import train_test_split
import matplotlib.pyplot as plt

# ============================================================
# Config
# ============================================================
device = torch.device("cpu")
print("device:", device)

SEEDS = [0, 1, 2]
NOISE_LEVELS = [0.0, 0.3, 0.5, 0.7]   # train-label noise
EPOCHS = 5
BATCH_SIZE = 256
LR = 1e-3
WEIGHT_DECAY = 1e-4
TRAIN_FRACTION = 0.25
VAL_FRACTION = 0.10
THRESH_DEAD = 1e-4
NUM_WORKERS = 0

HIDDEN_SIZES = [512, 256, 128]  # 3-hidden-layer MLP
OUTPUT_DIR = "mnist_noise_outputs"
os.makedirs(OUTPUT_DIR, exist_ok=True)

torch.manual_seed(0)
np.random.seed(0)
random.seed(0)

# MNIST normalization
MNIST_MEAN = (0.1307,)
MNIST_STD = (0.3081,)

# Variants
VARIANTS = [
    {"name": "relu", "act": "relu"},
    {"name": "leaky", "act": "leaky"},
    {"name": "mixed95", "act": "mixed", "mix_init": (1.5, -1.5)},  # ~95/5
    {"name": "mixed50", "act": "mixed", "mix_init": (0.0, 0.0)},    # 50/50
]

# ============================================================
# Utilities
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)

def grad_norm(model: nn.Module) -> float:
    total_sq = 0.0
    for p in model.parameters():
        if p.grad is not None:
            g = p.grad.detach()
            total_sq += float(g.norm(2).item() ** 2)
    return math.sqrt(total_sq)

def corrupt_labels(labels: np.ndarray, noise: float, seed: int) -> np.ndarray:
    """
    Flip a fraction of labels to a different random class.
    """
    if noise <= 0:
        return labels.copy()

    rng = np.random.RandomState(seed)
    labels = labels.copy()
    mask = rng.rand(len(labels)) < noise
    if mask.sum() == 0:
        return labels

    orig = labels[mask]
    # Guaranteed different from original: add 1..9 mod 10
    shifts = rng.randint(1, 10, size=mask.sum())
    new_labels = (orig + shifts) % 10
    labels[mask] = new_labels
    return labels

def dead_rate_from_tensor(x: torch.Tensor, threshold: float = THRESH_DEAD) -> float:
    if x is None:
        return float("nan")
    if x.dim() == 2:
        per_unit = x.abs().mean(dim=0)
    elif x.dim() == 4:
        per_unit = x.abs().mean(dim=(0, 2, 3))
    else:
        dims = tuple(range(x.dim() - 1))
        per_unit = x.abs().mean(dim=dims)
    return float((per_unit < threshold).float().mean().item())

class IndexedDataset(Dataset):
    def __init__(self, base_dataset, indices, targets_override=None):
        self.base_dataset = base_dataset
        self.indices = np.asarray(indices, dtype=np.int64)
        self.targets_override = None if targets_override is None else np.asarray(targets_override, dtype=np.int64)

    def __len__(self):
        return len(self.indices)

    def __getitem__(self, idx):
        x, y = self.base_dataset[int(self.indices[idx])]
        if self.targets_override is not None:
            y = int(self.targets_override[idx])
        return x, y

# ============================================================
# Activations
# ============================================================
class BaseActivation(nn.Module):
    def __init__(self):
        super().__init__()
        self.last_out = None

    def get_stats(self):
        return {
            "clean_w": float("nan"),
            "leak_w": float("nan"),
            "lambda": float("nan"),
            "alpha_mean": float("nan"),
            "pressure_mean": float("nan"),
        }

class ReLUAct(BaseActivation):
    def forward(self, x, mode="full"):
        y = F.relu(x)
        self.last_out = y.detach()
        return y

class LeakyAct(BaseActivation):
    def __init__(self, negative_slope=0.01):
        super().__init__()
        self.negative_slope = negative_slope

    def forward(self, x, mode="full"):
        y = F.leaky_relu(x, negative_slope=self.negative_slope)
        self.last_out = y.detach()
        return y

class MixedActivation(BaseActivation):
    """
    Clean path + bounded leak path + learnable mixture.
    Supports:
      - full
      - clean_only
      - leak_only
      - sum
    """
    def __init__(self, mix_init=(1.5, -1.5)):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(0.5))
        self.b = nn.Parameter(torch.tensor(-1.0))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(0.10)))
        self.mix_logits = nn.Parameter(torch.tensor(list(mix_init), dtype=torch.float32))

        self.last_stats = {
            "clean_w": float("nan"),
            "leak_w": float("nan"),
            "lambda": float("nan"),
            "alpha_mean": float("nan"),
            "pressure_mean": float("nan"),
        }

    def forward(self, x, mode="full"):
        clean = F.relu(x)
        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        leak = lam * alpha * torch.tanh(x)

        w = torch.softmax(self.mix_logits, dim=0)

        if mode == "full":
            y = w[0] * clean + w[1] * leak
        elif mode == "clean_only":
            y = clean
        elif mode == "leak_only":
            y = leak
        elif mode == "sum":
            y = clean + leak
        else:
            raise ValueError(f"Unknown mode: {mode}")

        self.last_out = y.detach()
        self.last_stats = {
            "clean_w": float(w[0].detach().cpu()),
            "leak_w": float(w[1].detach().cpu()),
            "lambda": float(lam.detach().cpu()),
            "alpha_mean": float(alpha.detach().mean().cpu()),
            "pressure_mean": float(pressure.detach().mean().cpu()),
        }
        return y

    def get_stats(self):
        return self.last_stats.copy()

# ============================================================
# Model
# ============================================================
class MLP(nn.Module):
    def __init__(self, input_dim, hidden_sizes, out_dim, activation="relu", mix_init=(1.5, -1.5)):
        super().__init__()
        self.activation_name = activation

        self.layers = nn.ModuleList()
        self.acts = nn.ModuleList()

        d = input_dim
        for h in hidden_sizes:
            self.layers.append(nn.Linear(d, h))

            if activation == "relu":
                self.acts.append(ReLUAct())
            elif activation == "leaky":
                self.acts.append(LeakyAct(negative_slope=0.01))
            elif activation == "mixed":
                self.acts.append(MixedActivation(mix_init=mix_init))
            else:
                raise ValueError(f"Unknown activation: {activation}")

            d = h

        self.out = nn.Linear(d, out_dim)
        self._init_weights()

    def _init_weights(self):
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.kaiming_normal_(m.weight, nonlinearity="relu")
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x, mode="full"):
        x = x.view(x.size(0), -1)
        for layer, act in zip(self.layers, self.acts):
            x = layer(x)
            x = act(x, mode=mode if self.activation_name == "mixed" else "full")
        return self.out(x)

    def mixed_layers(self):
        return [m for m in self.acts if isinstance(m, MixedActivation)]

# ============================================================
# Data
# ============================================================
transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize(MNIST_MEAN, MNIST_STD),
])

base_train = torchvision.datasets.MNIST(
    root="./data", train=True, download=True, transform=transform
)
base_test = torchvision.datasets.MNIST(
    root="./data", train=False, download=True, transform=transform
)

labels_all = np.array(base_train.targets)

def build_loaders(seed: int, label_noise: float):
    n_total = len(labels_all)
    all_idx = np.arange(n_total)

    # Subsample first, then split train/val stratified
    selected_idx, _ = train_test_split(
        all_idx,
        train_size=TRAIN_FRACTION,
        random_state=seed,
        stratify=labels_all
    )

    train_idx, val_idx = train_test_split(
        selected_idx,
        test_size=VAL_FRACTION,
        random_state=seed,
        stratify=labels_all[selected_idx]
    )

    train_labels = labels_all[train_idx]
    noisy_train_labels = corrupt_labels(train_labels, label_noise, seed=seed)

    train_ds = IndexedDataset(base_train, train_idx, noisy_train_labels)
    val_ds = IndexedDataset(base_train, val_idx, None)
    test_ds = base_test

    train_loader = DataLoader(
        train_ds,
        batch_size=BATCH_SIZE,
        shuffle=True,
        num_workers=NUM_WORKERS
    )
    val_loader = DataLoader(
        val_ds,
        batch_size=BATCH_SIZE,
        shuffle=False,
        num_workers=NUM_WORKERS
    )
    test_loader = DataLoader(
        test_ds,
        batch_size=BATCH_SIZE,
        shuffle=False,
        num_workers=NUM_WORKERS
    )
    return train_loader, val_loader, test_loader

# ============================================================
# Train / Eval
# ============================================================
def train_one_epoch(model, loader, optimizer, loss_fn):
    model.train()
    total_loss = 0.0
    total_seen = 0
    grad_vals = []

    for xb, yb in loader:
        xb = xb.to(device)
        yb = yb.to(device)

        optimizer.zero_grad(set_to_none=True)
        out = model(xb, mode="full")
        loss = loss_fn(out, yb)

        if not torch.isfinite(loss):
            return float("nan"), float("nan")

        loss.backward()
        grad_vals.append(grad_norm(model))
        optimizer.step()

        total_loss += loss.item() * xb.size(0)
        total_seen += xb.size(0)

    return total_loss / max(total_seen, 1), float(np.mean(grad_vals)) if grad_vals else float("nan")

@torch.no_grad()
def evaluate(model, loader, mode="full"):
    model.eval()
    loss_fn = nn.CrossEntropyLoss()
    total_loss = 0.0
    correct = 0
    total = 0

    for xb, yb in loader:
        xb = xb.to(device)
        yb = yb.to(device)

        out = model(xb, mode=mode)
        loss = loss_fn(out, yb)

        total_loss += loss.item() * xb.size(0)
        correct += (out.argmax(dim=1) == yb).sum().item()
        total += yb.size(0)

    return {
        "loss": total_loss / max(total, 1),
        "acc": correct / max(total, 1),
    }

@torch.no_grad()
def compute_dead_rate(model, loader):
    model.eval()
    act_sums = None
    n_seen = 0

    for xb, _ in loader:
        xb = xb.to(device)
        _ = model(xb, mode="full")

        if act_sums is None:
            act_sums = [torch.zeros(act.last_out.shape[1], device=device) for act in model.acts]

        for i, act in enumerate(model.acts):
            act_sums[i] += act.last_out.abs().sum(dim=0)

        n_seen += xb.size(0)

    if n_seen == 0 or act_sums is None:
        return float("nan")

    layer_dead = []
    for s in act_sums:
        mean_abs = s / n_seen
        layer_dead.append(float((mean_abs < THRESH_DEAD).float().mean().item()))

    return float(np.mean(layer_dead))

@torch.no_grad()
def collect_mixed_layerwise(model, loader):
    """
    Average layerwise stats over the whole loader.
    """
    model.eval()
    rows = []
    layer_counts = [0 for _ in model.mixed_layers()]
    sums = [
        {
            "clean_w": 0.0,
            "leak_w": 0.0,
            "lambda": 0.0,
            "alpha_mean": 0.0,
            "pressure_mean": 0.0,
            "dead_sum": 0.0,
            "act_abs_sum": None,
        }
        for _ in model.mixed_layers()
    ]

    n_seen = 0
    for xb, _ in loader:
        xb = xb.to(device)
        _ = model(xb, mode="full")
        bs = xb.size(0)
        n_seen += bs

        for i, act in enumerate(model.mixed_layers()):
            stats = act.get_stats()
            out = act.last_out
            if sums[i]["act_abs_sum"] is None:
                sums[i]["act_abs_sum"] = torch.zeros(out.shape[1], device=device)

            sums[i]["clean_w"] += stats["clean_w"] * bs
            sums[i]["leak_w"] += stats["leak_w"] * bs
            sums[i]["lambda"] += stats["lambda"] * bs
            sums[i]["alpha_mean"] += stats["alpha_mean"] * bs
            sums[i]["pressure_mean"] += stats["pressure_mean"] * bs
            sums[i]["act_abs_sum"] += out.abs().sum(dim=0)

    if n_seen == 0:
        return []

    for i, act in enumerate(model.mixed_layers(), start=1):
        mean_abs = sums[i - 1]["act_abs_sum"] / n_seen
        rows.append({
            "layer": i,
            "clean_w": sums[i - 1]["clean_w"] / n_seen,
            "leak_w": sums[i - 1]["leak_w"] / n_seen,
            "lambda": sums[i - 1]["lambda"] / n_seen,
            "alpha_mean": sums[i - 1]["alpha_mean"] / n_seen,
            "pressure_mean": sums[i - 1]["pressure_mean"] / n_seen,
            "dead_rate": float((mean_abs < THRESH_DEAD).float().mean().item()),
        })

    return rows

@torch.no_grad()
def eval_mixed_modes(model, loader):
    return {
        "test_acc_full": evaluate(model, loader, mode="full")["acc"],
        "test_acc_clean_only": evaluate(model, loader, mode="clean_only")["acc"],
        "test_acc_leak_only": evaluate(model, loader, mode="leak_only")["acc"],
        "test_acc_sum": evaluate(model, loader, mode="sum")["acc"],
    }

# ============================================================
# Experiment
# ============================================================
results = []
layerwise_rows = []
train_history_rows = []

start_all = time.time()
print("\nRunning MNIST label-noise stress test...")

for noise in NOISE_LEVELS:
    print(f"\n=== Noise level = {noise} ===")
    for variant in VARIANTS:
        for seed in SEEDS:
            set_seed(seed)
            print(f"\n--- {variant['name']} | seed={seed} ---")

            train_loader, val_loader, test_loader = build_loaders(seed, label_noise=noise)

            model = MLP(
                input_dim=28 * 28,
                hidden_sizes=HIDDEN_SIZES,
                out_dim=10,
                activation=variant["act"],
                mix_init=variant.get("mix_init", (1.5, -1.5)),
            ).to(device)

            optimizer = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)
            loss_fn = nn.CrossEntropyLoss()

            best_state = None
            best_val_loss = float("inf")
            best_val_acc = 0.0
            best_epoch = -1

            epoch_grad_norms = []
            epoch_train_losses = []
            epoch_val_losses = []

            t0 = time.time()

            for epoch in range(1, EPOCHS + 1):
                train_loss, gnorm = train_one_epoch(model, train_loader, optimizer, loss_fn)
                if not np.isfinite(train_loss):
                    print(f"  epoch {epoch:02d} | non-finite loss, stopping early")
                    break

                val_metrics = evaluate(model, val_loader, mode="full")
                epoch_train_losses.append(train_loss)
                epoch_val_losses.append(val_metrics["loss"])
                epoch_grad_norms.append(gnorm)

                train_history_rows.append({
                    "noise": noise,
                    "variant": variant["name"],
                    "seed": seed,
                    "epoch": epoch,
                    "train_loss": train_loss,
                    "val_loss": val_metrics["loss"],
                    "val_acc": val_metrics["acc"],
                    "grad_norm": gnorm,
                })

                if val_metrics["loss"] < best_val_loss - 1e-6:
                    best_val_loss = val_metrics["loss"]
                    best_val_acc = val_metrics["acc"]
                    best_epoch = epoch
                    best_state = deepcopy(model.state_dict())

                print(
                    f"  epoch {epoch:02d} | train_loss={train_loss:.4f} | "
                    f"val_loss={val_metrics['loss']:.4f} | grad_norm={gnorm:.2f}"
                )

            if best_state is not None:
                model.load_state_dict(best_state)

            test_clean = evaluate(model, test_loader, mode="full")
            dead = compute_dead_rate(model, val_loader)
            run_time = time.time() - t0

            row = {
                "noise": noise,
                "variant": variant["name"],
                "activation": variant["act"],
                "seed": seed,
                "epochs_ran": len(epoch_train_losses),
                "best_epoch": best_epoch,
                "best_val_loss": best_val_loss,
                "best_val_acc": best_val_acc,
                "test_acc_full": test_clean["acc"],
                "test_loss_full": test_clean["loss"],
                "dead_rate": dead,
                "train_time_sec": run_time,
                "grad_norm_mean": float(np.mean(epoch_grad_norms)) if epoch_grad_norms else float("nan"),
                "grad_norm_max": float(np.max(epoch_grad_norms)) if epoch_grad_norms else float("nan"),
            }

            if variant["act"] == "mixed":
                mixed_diag = eval_mixed_modes(model, test_loader)
                row.update(mixed_diag)

                mixed_layers = model.mixed_layers()
                row["mix_clean_mean"] = float(np.mean([m.get_stats()["clean_w"] for m in mixed_layers]))
                row["mix_leak_mean"] = float(np.mean([m.get_stats()["leak_w"] for m in mixed_layers]))
                row["lambda_mean"] = float(np.mean([m.get_stats()["lambda"] for m in mixed_layers]))
                row["alpha_mean"] = float(np.mean([m.get_stats()["alpha_mean"] for m in mixed_layers]))
                row["pressure_mean"] = float(np.mean([m.get_stats()["pressure_mean"] for m in mixed_layers]))

                # layerwise stats
                probe_rows = collect_mixed_layerwise(model, val_loader)
                for r in probe_rows:
                    r.update({
                        "noise": noise,
                        "variant": variant["name"],
                        "seed": seed,
                    })
                    layerwise_rows.append(r)

                print(
                    f"      mix clean/leak = {row['mix_clean_mean']:.3f}/{row['mix_leak_mean']:.3f}, "
                    f"lambda={row['lambda_mean']:.3f}, alpha={row['alpha_mean']:.3f}"
                )

            results.append(row)

            print(
                f"FINAL: acc={row['test_acc_full']:.4f}, dead={row['dead_rate']:.4f}, "
                f"best_val={row['best_val_loss']:.4f}, time={run_time:.1f}s"
            )

# ============================================================
# Save
# ============================================================
results_df = pd.DataFrame(results)
layerwise_df = pd.DataFrame(layerwise_rows)
history_df = pd.DataFrame(train_history_rows)

results_csv = os.path.join(OUTPUT_DIR, "mnist_noise_results.csv")
layerwise_csv = os.path.join(OUTPUT_DIR, "mnist_noise_layerwise.csv")
history_csv = os.path.join(OUTPUT_DIR, "mnist_noise_history.csv")

results_df.to_csv(results_csv, index=False)
layerwise_df.to_csv(layerwise_csv, index=False)
history_df.to_csv(history_csv, index=False)

print("\nSaved:")
print(" -", results_csv)
print(" -", layerwise_csv)
print(" -", history_csv)

# ============================================================
# Summaries
# ============================================================
pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 220)

print("\n================ SUMMARY BY NOISE =================")
summary = results_df.groupby(["noise", "variant"])[
    ["test_acc_full", "dead_rate", "best_val_loss", "train_time_sec", "grad_norm_mean"]
].agg(["mean", "std"]).round(4)
print(summary)

if "test_acc_clean_only" in results_df.columns:
    print("\n================ MIXED DIAGNOSTICS =================")
    mix_summary = results_df[results_df["activation"] == "mixed"].groupby(["noise", "variant"])[
        ["test_acc_full", "test_acc_clean_only", "test_acc_leak_only", "test_acc_sum", "mix_clean_mean", "mix_leak_mean", "lambda_mean", "alpha_mean", "pressure_mean"]
    ].agg(["mean", "std"]).round(4)
    print(mix_summary)

if not layerwise_df.empty:
    print("\n================ LAYERWISE SUMMARY (MIXED) ================")
    layer_summary = layerwise_df.groupby(["variant", "layer"])[
        ["clean_w", "leak_w", "lambda", "alpha_mean", "pressure_mean", "dead_rate"]
    ].agg(["mean", "std"]).round(4)
    print(layer_summary)

# ============================================================
# Plots: paper-ready multi-panel figure
# ============================================================
order = [v["name"] for v in VARIANTS]
noise_sorted = sorted(NOISE_LEVELS)

metric_map = {
    "test_acc_full": ("Test accuracy", "MNIST label-noise stress test"),
    "best_val_loss": ("Best validation loss", "MNIST label-noise stress test"),
    "dead_rate": ("Dead rate", "MNIST label-noise stress test"),
    "grad_norm_mean": ("Gradient norm", "MNIST label-noise stress test"),
}

fig, axes = plt.subplots(2, 2, figsize=(14, 10))
axes = axes.ravel()

for ax, metric in zip(axes, ["test_acc_full", "best_val_loss", "dead_rate", "grad_norm_mean"]):
    for variant_name in order:
        sub = results_df[results_df["variant"] == variant_name].groupby("noise")[metric].agg(["mean", "std"]).reindex(noise_sorted)
        ax.errorbar(
            noise_sorted,
            sub["mean"].values,
            yerr=sub["std"].values,
            marker="o",
            capsize=3,
            label=variant_name,
        )
    ax.set_xlabel("Label noise")
    ax.set_ylabel(metric_map[metric][0])
