        ax.errorbar(layers, clean_mean, yerr=clean_std, marker="o", capsize=3, label="clean weight")
        ax.errorbar(layers, leak_mean, yerr=leak_std, marker="o", capsize=3, label="leak weight")
        ax.set_xlabel("Layer")
        ax.set_title(f"Layerwise weights — {variant_name}")
        ax.grid(True, alpha=0.3)
