import os
import math
import random
import time
from dataclasses import dataclass
from typing import Dict, List, Tuple

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
import torchvision
import torchvision.transforms as transforms
from torch.utils.data import Dataset, DataLoader
import matplotlib.pyplot as plt

# ============================================================
# Config
# ============================================================
device = torch.device("cpu")
print("device:", device)

SEEDS = [0, 1, 2]
NOISE_LEVELS = [0.8, 0.9]   # training label corruption only
EPOCHS = 10
BATCH_SIZE = 256
LR = 1e-3
WEIGHT_DECAY = 1e-4
VAL_FRACTION = 0.10
THRESH_DEAD = 1e-4

HIDDEN_DIMS = (512, 256, 128)

OUTPUT_DIR = "mnist_extreme_noise_outputs"
os.makedirs(OUTPUT_DIR, exist_ok=True)

torch.set_num_threads(max(1, os.cpu_count() or 1))
torch.backends.cudnn.benchmark = False

MNIST_MEAN = (0.1307,)
MNIST_STD = (0.3081,)

VARIANTS = [
    {"name": "relu",     "act": "relu"},
    {"name": "leaky",    "act": "leaky"},
    {"name": "mixed95",  "act": "mixed", "mix_init": (1.5, -1.5)},  # ~95/5
    {"name": "mixed50",  "act": "mixed", "mix_init": (0.0, 0.0)},    # 50/50
]

# ============================================================
# Utilities
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)

def grad_norm(model: nn.Module) -> float:
    total_sq = 0.0
    for p in model.parameters():
        if p.grad is not None:
            g = p.grad.detach()
            total_sq += float(g.norm(2).item() ** 2)
    return math.sqrt(total_sq)

def dead_rate_from_tensor(x: torch.Tensor, threshold: float = THRESH_DEAD) -> float:
    if x is None:
        return float("nan")
    if x.dim() == 2:
        per_unit = x.abs().mean(dim=0)
    else:
        dims = tuple(range(x.dim() - 1))
        per_unit = x.abs().mean(dim=dims)
    return float((per_unit < threshold).float().mean().item())

# ============================================================
# Datasets
# ============================================================
class IndexedDataset(Dataset):
    def __init__(self, base_dataset, indices: List[int]):
        self.base = base_dataset
        self.indices = list(indices)

    def __len__(self):
        return len(self.indices)

    def __getitem__(self, idx):
        return self.base[self.indices[idx]]

class NoisyLabelDataset(Dataset):
    def __init__(self, base_dataset, indices: List[int], noisy_label_map: Dict[int, int]):
        self.base = base_dataset
        self.indices = list(indices)
        self.noisy_label_map = noisy_label_map

    def __len__(self):
        return len(self.indices)

    def __getitem__(self, idx):
        base_idx = self.indices[idx]
        x, y = self.base[base_idx]
        if base_idx in self.noisy_label_map:
            y = int(self.noisy_label_map[base_idx])
        return x, y

train_transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize(MNIST_MEAN, MNIST_STD),
])

eval_transform = transforms.Compose([
    transforms.ToTensor(),
    transforms.Normalize(MNIST_MEAN, MNIST_STD),
])

base_train_aug = torchvision.datasets.MNIST(
    root="./data", train=True, download=True, transform=train_transform
)
base_train_eval = torchvision.datasets.MNIST(
    root="./data", train=True, download=True, transform=eval_transform
)
base_test = torchvision.datasets.MNIST(
    root="./data", train=False, download=True, transform=eval_transform
)

train_targets = np.array(base_train_eval.targets, dtype=np.int64)

def build_loaders(seed: int, noise_level: float):
    rng = np.random.RandomState(seed)
    n_total = len(base_train_eval)
    perm = rng.permutation(n_total)

    n_val = int(n_total * VAL_FRACTION)
    val_idx = perm[:n_val].tolist()
    train_idx = perm[n_val:].tolist()

    noisy_map = {}
    noise_rng = np.random.RandomState(seed + int(noise_level * 1000) + 17)
    for idx in train_idx:
        if noise_rng.rand() < noise_level:
            true = int(train_targets[idx])
            new_label = noise_rng.randint(0, 10)
            while new_label == true:
                new_label = noise_rng.randint(0, 10)
            noisy_map[idx] = int(new_label)

    train_ds = NoisyLabelDataset(base_train_aug, train_idx, noisy_map)
    val_ds = IndexedDataset(base_train_eval, val_idx)
    test_ds = base_test

    train_loader = DataLoader(
        train_ds, batch_size=BATCH_SIZE, shuffle=True, num_workers=0, pin_memory=False
    )
    val_loader = DataLoader(
        val_ds, batch_size=BATCH_SIZE, shuffle=False, num_workers=0, pin_memory=False
    )
    test_loader = DataLoader(
        test_ds, batch_size=BATCH_SIZE * 2, shuffle=False, num_workers=0, pin_memory=False
    )
    return train_loader, val_loader, test_loader, len(noisy_map), len(train_idx)

# ============================================================
# Activations
# ============================================================
class BaseActivation(nn.Module):
    def __init__(self):
        super().__init__()
        self.last_out = None

    def get_stats(self):
        return {
            "clean_w": float("nan"),
            "leak_w": float("nan"),
            "lambda": float("nan"),
            "alpha_mean": float("nan"),
            "pressure_mean": float("nan"),
        }

class ReLUAct(BaseActivation):
    def forward(self, x, mode="full"):
        y = F.relu(x)
        self.last_out = y.detach()
        return y

class LeakyAct(BaseActivation):
    def __init__(self, negative_slope=0.01):
        super().__init__()
        self.negative_slope = negative_slope

    def forward(self, x, mode="full"):
        y = F.leaky_relu(x, negative_slope=self.negative_slope)
        self.last_out = y.detach()
        return y

class MixedActivation(BaseActivation):
    def __init__(self, mix_init=(1.5, -1.5)):
        super().__init__()
        self.a = nn.Parameter(torch.tensor(0.5))
        self.b = nn.Parameter(torch.tensor(-1.0))
        self.logit_lambda = nn.Parameter(torch.logit(torch.tensor(0.10)))
        self.mix_logits = nn.Parameter(torch.tensor(list(mix_init), dtype=torch.float32))

        self.last_stats = {
            "clean_w": float("nan"),
            "leak_w": float("nan"),
            "lambda": float("nan"),
            "alpha_mean": float("nan"),
            "pressure_mean": float("nan"),
        }

    def forward(self, x, mode="full"):
        clean = F.relu(x)
        pressure = torch.abs(x)
        alpha = torch.sigmoid(self.a * pressure + self.b)
        lam = torch.sigmoid(self.logit_lambda)
        leak = lam * alpha * torch.tanh(x)

        w = torch.softmax(self.mix_logits, dim=0)

        if mode == "full":
            y = w[0] * clean + w[1] * leak
        elif mode == "clean_only":
            y = clean
        elif mode == "leak_only":
            y = leak
        elif mode == "sum":
            y = clean + leak
        else:
            raise ValueError(f"Unknown mode: {mode}")

        self.last_out = y.detach()
        self.last_stats = {
            "clean_w": float(w[0].detach().cpu()),
            "leak_w": float(w[1].detach().cpu()),
            "lambda": float(lam.detach().cpu()),
            "alpha_mean": float(alpha.detach().mean().cpu()),
            "pressure_mean": float(pressure.detach().mean().cpu()),
        }
        return y

    def get_stats(self):
        return self.last_stats.copy()

# ============================================================
# Model
# ============================================================
class MLP(nn.Module):
    def __init__(self, variant_name: str, act_type: str, mix_init=(1.5, -1.5)):
        super().__init__()
        self.variant_name = variant_name
        self.act_type = act_type

        dims = [784, *HIDDEN_DIMS]
        self.fcs = nn.ModuleList()
        self.acts = nn.ModuleList()

        for d_in, d_out in zip(dims[:-1], dims[1:]):
            self.fcs.append(nn.Linear(d_in, d_out))
            if act_type == "relu":
                self.acts.append(ReLUAct())
            elif act_type == "leaky":
                self.acts.append(LeakyAct(negative_slope=0.01))
            elif act_type == "mixed":
                self.acts.append(MixedActivation(mix_init=mix_init))
            else:
                raise ValueError(f"Unknown act_type: {act_type}")

        self.classifier = nn.Linear(dims[-1], 10)
        self._init_weights()

    def _init_weights(self):
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.kaiming_normal_(m.weight, nonlinearity="relu")
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x, mode="full"):
        x = x.view(x.size(0), -1)
        for fc, act in zip(self.fcs, self.acts):
            x = fc(x)
            x = act(x, mode=mode if self.act_type == "mixed" else "full")
        return self.classifier(x)

    def mixed_layers(self):
        return [m for m in self.acts if isinstance(m, MixedActivation)]

# ============================================================
# Train / Eval
# ============================================================
def train_one_epoch(model, loader, optimizer, loss_fn):
    model.train()
    total_loss = 0.0
    total = 0
    gnorms = []

    for xb, yb in loader:
        xb = xb.to(device)
        yb = yb.to(device)

        optimizer.zero_grad(set_to_none=True)
        out = model(xb, mode="full")
        loss = loss_fn(out, yb)

        if not torch.isfinite(loss):
            return float("nan"), float("nan")

        loss.backward()
        gnorms.append(grad_norm(model))
        optimizer.step()

        total_loss += loss.item() * xb.size(0)
        total += xb.size(0)

    return total_loss / max(total, 1), float(np.mean(gnorms)) if gnorms else float("nan")

@torch.no_grad()
def evaluate(model, loader, mode="full"):
    model.eval()
    loss_fn = nn.CrossEntropyLoss()
    total_loss = 0.0
    correct = 0
    total = 0

    for xb, yb in loader:
        xb = xb.to(device)
        yb = yb.to(device)
        out = model(xb, mode=mode)
        loss = loss_fn(out, yb)

        total_loss += loss.item() * xb.size(0)
        pred = out.argmax(dim=1)
        correct += (pred == yb).sum().item()
        total += yb.size(0)

    return {
        "loss": total_loss / max(total, 1),
        "acc": correct / max(total, 1),
    }

@torch.no_grad()
def collect_layerwise_diagnostics(model, loader, threshold=THRESH_DEAD):
    model.eval()
    xb, _ = next(iter(loader))
    xb = xb.to(device)
    _ = model(xb, mode="full")

    rows = []
    for layer_id, act in enumerate(model.mixed_layers(), start=1):
        out = act.last_out
        stats = act.get_stats()
        rows.append({
            "layer": layer_id,
            "dead_rate": dead_rate_from_tensor(out, threshold=threshold),
            "clean_w": stats["clean_w"],
            "leak_w": stats["leak_w"],
            "lambda": stats["lambda"],
            "alpha_mean": stats["alpha_mean"],
            "pressure_mean": stats["pressure_mean"],
        })
    return rows

def eval_mixed_modes(model, loader):
    return {
        "test_acc_clean_only": evaluate(model, loader, mode="clean_only")["acc"],
        "test_acc_leak_only": evaluate(model, loader, mode="leak_only")["acc"],
        "test_acc_sum": evaluate(model, loader, mode="sum")["acc"],
    }

# ============================================================
# Run experiment
# ============================================================
results = []
layerwise_rows = []
history_rows = []

print("\nRunning MNIST extreme label-noise stress test...")
start_all = time.time()

for noise_level in NOISE_LEVELS:
    print(f"\n=== Noise level = {noise_level} ===")
    for variant in VARIANTS:
        for seed in SEEDS:
            set_seed(seed)
            print(f"\n--- {variant['name']} | seed={seed} ---")

            train_loader, val_loader, test_loader, noisy_count, train_count = build_loaders(seed, noise_level)
            model = MLP(
                variant_name=variant["name"],
                act_type=variant["act"],
                mix_init=variant.get("mix_init", (1.5, -1.5)),
            ).to(device)

            optimizer = optim.AdamW(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)
            loss_fn = nn.CrossEntropyLoss()

            best_state = None
            best_val_loss = float("inf")
            best_val_acc = 0.0
            best_epoch = -1
            epoch_grad_norms = []
            t0 = time.time()

            for epoch in range(1, EPOCHS + 1):
                train_loss, gnorm = train_one_epoch(model, train_loader, optimizer, loss_fn)
                val_m = evaluate(model, val_loader, mode="full")

                history_rows.append({
                    "noise": noise_level,
                    "variant": variant["name"],
                    "seed": seed,
                    "epoch": epoch,
                    "train_loss": train_loss,
                    "val_loss": val_m["loss"],
                    "val_acc": val_m["acc"],
                    "grad_norm": gnorm,
                })

                epoch_grad_norms.append(gnorm)

                if val_m["loss"] < best_val_loss - 1e-6:
                    best_val_loss = val_m["loss"]
                    best_val_acc = val_m["acc"]
                    best_epoch = epoch
                    best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}

                print(
                    f"  epoch {epoch:02d} | train_loss={train_loss:.4f} | "
                    f"val_loss={val_m['loss']:.4f} | grad_norm={gnorm:.2f}"
                )

            if best_state is not None:
                model.load_state_dict(best_state)

            test_clean = evaluate(model, test_loader, mode="full")

            row = {
                "noise": noise_level,
                "variant": variant["name"],
                "act": variant["act"],
                "seed": seed,
                "train_count": train_count,
                "noisy_count": noisy_count,
                "noise_fraction_actual": noisy_count / max(train_count, 1),
                "epochs_ran": EPOCHS,
                "best_epoch": best_epoch,
                "best_val_loss": best_val_loss,
                "best_val_acc": best_val_acc,
                "test_acc_full": test_clean["acc"],
                "test_loss_full": test_clean["loss"],
                "dead_rate": float("nan"),
                "train_time_sec": time.time() - t0,
                "grad_norm_mean": float(np.mean(epoch_grad_norms)) if epoch_grad_norms else float("nan"),
                "grad_norm_max": float(np.max(epoch_grad_norms)) if epoch_grad_norms else float("nan"),
            }

            probe_loader = DataLoader(
                IndexedDataset(base_train_eval, list(range(0, 2048))),
                batch_size=256, shuffle=False, num_workers=0
            )
            if variant["act"] == "mixed":
                mixed_modes = eval_mixed_modes(model, test_loader)
                row.update(mixed_modes)

                mixed_layers = model.mixed_layers()
                row["mix_clean_mean"] = float(np.mean([m.get_stats()["clean_w"] for m in mixed_layers]))
                row["mix_leak_mean"] = float(np.mean([m.get_stats()["leak_w"] for m in mixed_layers]))
                row["lambda_mean"] = float(np.mean([m.get_stats()["lambda"] for m in mixed_layers]))
                row["alpha_mean"] = float(np.mean([m.get_stats()["alpha_mean"] for m in mixed_layers]))
                row["pressure_mean"] = float(np.mean([m.get_stats()["pressure_mean"] for m in mixed_layers]))

                layer_rows = collect_layerwise_diagnostics(model, probe_loader, threshold=THRESH_DEAD)
                if layer_rows:
                    row["dead_rate"] = float(np.mean([r["dead_rate"] for r in layer_rows if np.isfinite(r["dead_rate"])]))
                    for r in layer_rows:
                        r.update({
                            "noise": noise_level,
                            "variant": variant["name"],
                            "seed": seed,
                        })
                        layerwise_rows.append(r)
            else:
                # For plain activations, estimate dead rate from the hidden outputs captured during the last forward pass
                _ = model(next(iter(probe_loader))[0].to(device), mode="full")
                dead_vals = []
                for act_mod in model.acts:
                    out = act_mod.last_out
                    dead_vals.append(dead_rate_from_tensor(out, threshold=THRESH_DEAD))
                row["dead_rate"] = float(np.mean(dead_vals)) if dead_vals else float("nan")

            results.append(row)

            print(
                f"FINAL: acc={row['test_acc_full']:.4f}, dead={row['dead_rate']:.4f}, "
                f"best_val={row['best_val_loss']:.4f}, time={row['train_time_sec']:.1f}s"
            )
            if variant["act"] == "mixed":
                print(
                    f"      mix clean/leak = {row['mix_clean_mean']:.3f}/{row['mix_leak_mean']:.3f}, "
                    f"lambda={row['lambda_mean']:.3f}, alpha={row['alpha_mean']:.3f}"
                )

# ============================================================
# Save tables
# ============================================================
results_df = pd.DataFrame(results)
history_df = pd.DataFrame(history_rows)
layerwise_df = pd.DataFrame(layerwise_rows)

results_csv = os.path.join(OUTPUT_DIR, "mnist_noise_results.csv")
history_csv = os.path.join(OUTPUT_DIR, "mnist_noise_history.csv")
layerwise_csv = os.path.join(OUTPUT_DIR, "mnist_noise_layerwise.csv")

results_df.to_csv(results_csv, index=False)
history_df.to_csv(history_csv, index=False)
layerwise_df.to_csv(layerwise_csv, index=False)

print("\nSaved:")
print(" -", results_csv)
print(" -", history_csv)
print(" -", layerwise_csv)

# ============================================================
# Summaries
# ============================================================
pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 220)

print("\n================ SUMMARY BY NOISE ================")
summary = results_df.groupby(["noise", "variant"])[
    ["test_acc_full", "dead_rate", "best_val_loss", "train_time_sec", "grad_norm_mean", "grad_norm_max"]
].agg(["mean", "std"]).round(4)
print(summary)

if not layerwise_df.empty:
    print("\n================ LAYERWISE SUMMARY (MIXED) ================")
    layer_summary = layerwise_df.groupby(["noise", "variant", "layer"])[
        ["clean_w", "leak_w", "lambda", "alpha_mean", "pressure_mean", "dead_rate"]
    ].agg(["mean", "std"]).round(4)
    print(layer_summary)

print("\n================ BEST CONFIGS BY NOISE ================")
best_by_noise = results_df.sort_values(["noise", "test_acc_full"], ascending=[True, False]).groupby("noise").head(5)
print(best_by_noise[["noise", "variant", "seed", "test_acc_full", "dead_rate", "best_val_loss", "grad_norm_mean"]].to_string(index=False))

# ============================================================
# Plots: multi-panel summary figure
# ============================================================
variant_order = [v["name"] for v in VARIANTS]
noise_order = sorted(results_df["noise"].unique())

def plot_metric_panel(ax, metric, title, ylabel):
    for variant in variant_order:
        sub = results_df[results_df["variant"] == variant].groupby("noise")[metric].agg(["mean", "std"]).reindex(noise_order)
        ax.errorbar(noise_order, sub["mean"].values, yerr=sub["std"].values, marker="o", capsize=4, label=variant)
    ax.set_title(title)
    ax.set_xlabel("Label noise")
    ax.set_ylabel(ylabel)
    ax.grid(True, alpha=0.3)

fig, axes = plt.subplots(2, 2, figsize=(14, 10), sharex=True)
plot_metric_panel(axes[0, 0], "test_acc_full", "Test accuracy vs label noise", "Accuracy")
plot_metric_panel(axes[0, 1], "dead_rate", "Dead rate vs label noise", "Dead rate")
plot_metric_panel(axes[1, 0], "best_val_loss", "Best validation loss vs label noise", "Best val loss")
plot_metric_panel(axes[1, 1], "grad_norm_mean", "Mean gradient norm vs label noise", "Gradient norm")

for ax in axes.ravel():
    ax.set_xticks(noise_order)

axes[0, 0].legend(loc="best", fontsize=9)
plt.tight_layout()
summary_plot = os.path.join(OUTPUT_DIR, "mnist_noise_summary_panels.png")
plt.savefig(summary_plot, dpi=220)
plt.close()

# ============================================================
# Plots: layerwise clean/leak panels for mixed variants
# ============================================================
if not layerwise_df.empty:
    mixed_variants = [v["name"] for v in VARIANTS if v["act"] == "mixed"]
    fig, axes = plt.subplots(1, len(mixed_variants), figsize=(14, 5), sharey=True)
    if len(mixed_variants) == 1:
        axes = [axes]

    for ax, variant in zip(axes, mixed_variants):
        for noise in noise_order:
            sub = layerwise_df[(layerwise_df["variant"] == variant) & (layerwise_df["noise"] == noise)]
            grp = sub.groupby("layer")[["clean_w", "leak_w"]].mean().reset_index()
            ax.plot(grp["layer"], grp["clean_w"], marker="o", linestyle="-", label=f"clean w | noise={noise}")
            ax.plot(grp["layer"], grp["leak_w"], marker="o", linestyle="--", label=f"leak w | noise={noise}")

        ax.set_title(f"Layerwise weights: {variant}")
        ax.set_xlabel("Layer")
        ax.grid(True, alpha=0.3)

    axes[0].set_ylabel("Weight")
    axes[0].legend(fontsize=8)
    plt.tight_layout()
    layerwise_plot = os.path.join(OUTPUT_DIR, "mnist_layerwise_clean_vs_leak.png")
    plt.savefig(layerwise_plot, dpi=220)
    plt.close()

print("\nSaved figures:")
print(" -", summary_plot)
if not layerwise_df.empty:
    print(" -", layerwise_plot)

print("\nDone.")
